insert into public.learning_levels (id, code, slug, name, cefr, description) values ('92b6ddd3-64f7-519f-adb8-e85a817587e7', 1, 'beginner-english', 'Beginner English', 'Pre-A1 to A1', 'Alphabet, sounds, numbers, your first 500 words and the simple present. Learn to introduce yourself.');
insert into public.learning_levels (id, code, slug, name, cefr, description) values ('d17b31cb-2ed4-5377-b203-17024625bd0e', 2, 'elementary-english', 'Elementary English', 'A2', 'About 1,500 words, past and future, simple paragraphs, short conversations and basic listening.');
insert into public.learning_levels (id, code, slug, name, cefr, description) values ('0f3f9da3-4381-5af6-82b4-4c09bf3b6cb2', 3, 'intermediate-english', 'Intermediate English', 'B1', 'About 3,000 words, all main tenses, linking words, opinion paragraphs and everyday lectures.');
insert into public.learning_levels (id, code, slug, name, cefr, description) values ('f2e3e98f-5cdd-55f6-99a4-8cf76086d8bb', 4, 'pte-preparation', 'PTE Preparation', 'B2', 'Academic vocabulary, complex sentences, essays, note-taking and all 22 PTE task types.');
