insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'l1-u1-first-steps', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'Unit 1: First steps', 'Letters and your first words: say hello and introduce yourself.', 1, '[{"id": "u11-t1", "type": "single_choice", "prompt": "Which of these is a vowel?", "options": ["k", "o", "s"], "answer": "o", "explanation": "The vowels are a, e, i, o and u."}, {"id": "u11-t2", "type": "single_choice", "prompt": "Which letter comes after \"g\"?", "options": ["f", "h", "j"], "answer": "h", "explanation": "The order is ... f, g, h, i, j ..."}, {"id": "u11-t3", "type": "single_choice", "prompt": "Which sentence uses capital letters correctly?", "options": ["i live in london.", "I live in London.", "I Live In london."], "answer": "I live in London.", "explanation": "Use a capital for \"I\", the first word, and names of places."}, {"id": "u11-t4", "type": "single_choice", "prompt": "It is 9 at night and you are going to bed. What do you say?", "options": ["Good morning", "Good night", "Hello"], "answer": "Good night", "explanation": "*Good night* is what we say late in the evening or before sleep."}, {"id": "u11-t5", "type": "single_choice", "prompt": "Complete: \"Hello, my ___ is Ana.\"", "options": ["name", "names", "named"], "answer": "name", "explanation": "We say *My name is ...* to introduce ourselves."}]'::jsonb, 'published');
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('d8107047-9780-5b15-b638-1478f05d58ca', 'l1-u2-words-and-sentences', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'Unit 2: Words and sentences', 'Kinds of words, one and many, and words like I, you and they.', 2, '[{"id": "u12-t1", "type": "single_choice", "prompt": "In \"The cat sleeps\", which word is a verb?", "options": ["The", "cat", "sleeps"], "answer": "sleeps", "explanation": "A verb is an action or state word: *sleeps*."}, {"id": "u12-t2", "type": "single_choice", "prompt": "What is the plural of \"box\"?", "options": ["boxs", "boxes", "boxies"], "answer": "boxes", "explanation": "Nouns ending in -x add -es: box → boxes."}, {"id": "u12-t3", "type": "single_choice", "prompt": "What is the plural of \"child\"?", "options": ["childs", "children", "childes"], "answer": "children", "explanation": "*Child* is irregular: one child, two children."}, {"id": "u12-t4", "type": "single_choice", "prompt": "Maria is my friend. ___ is from Spain.", "options": ["He", "She", "They"], "answer": "She", "explanation": "We use *she* for one woman or girl."}, {"id": "u12-t5", "type": "single_choice", "prompt": "Tom and I are students. ___ study English.", "options": ["We", "They", "You"], "answer": "We", "explanation": "*Tom and I* means *we*."}]'::jsonb, 'published');
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('db0627b0-e166-5c63-9f64-77cce74979fd', 'l1-u3-me-and-my-day', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'Unit 3: Me and my day', 'Talk about yourself, your things and your daily routine.', 3, '[{"id": "u13-t1", "type": "single_choice", "prompt": "She ___ a doctor.", "options": ["am", "is", "are"], "answer": "is", "explanation": "*She* goes with *is*."}, {"id": "u13-t2", "type": "single_choice", "prompt": "We ___ a garden.", "options": ["have", "has", "haves"], "answer": "have", "explanation": "*We* goes with *have*."}, {"id": "u13-t3", "type": "single_choice", "prompt": "Tom ___ to work by train.", "options": ["go", "goes", "going"], "answer": "goes", "explanation": "*Tom* = *he*, so *goes*."}, {"id": "u13-t4", "type": "single_choice", "prompt": "The meeting is ___ Tuesday.", "options": ["in", "on", "at"], "answer": "on", "explanation": "We use *on* with days."}, {"id": "u13-t5", "type": "single_choice", "prompt": "Which is 70?", "options": ["seventeen", "seventy", "seven"], "answer": "seventy", "explanation": "70 is *seventy*."}, {"id": "u13-t6", "type": "single_choice", "prompt": "___ your brother live in Paris?", "options": ["Do", "Does", "Is"], "answer": "Does", "explanation": "Questions with *he* use *Does*."}]'::jsonb, 'published');
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('96fc4244-4351-5fc7-9691-4c82cbd1f436', 'l1-u4-people-and-places', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'Unit 4: People and places', 'Talk about your family, what is around you and what you can do.', 4, '[{"id": "u14-t1", "type": "single_choice", "prompt": "My mother''s sister is my ___.", "options": ["aunt", "cousin", "niece"], "answer": "aunt", "explanation": "Your parent''s sister is your *aunt*."}, {"id": "u14-t2", "type": "single_choice", "prompt": "They love ___ new house.", "options": ["there", "their", "they''re"], "answer": "their", "explanation": "*their* shows it belongs to them."}, {"id": "u14-t3", "type": "single_choice", "prompt": "___ two cafés on my street.", "options": ["There is", "There are", "It is"], "answer": "There are", "explanation": "Two cafés: *There are*."}, {"id": "u14-t4", "type": "single_choice", "prompt": "The cat is ___ the box. It is inside.", "options": ["in", "on", "between"], "answer": "in", "explanation": "Inside = *in*."}, {"id": "u14-t5", "type": "single_choice", "prompt": "Which is correct?", "options": ["She can sings.", "She can sing.", "She cans sing."], "answer": "She can sing.", "explanation": "*can* + base verb."}, {"id": "u14-t6", "type": "single_choice", "prompt": "Which is correct?", "options": ["The bird hurt it''s wing.", "The bird hurt its wing.", "The bird hurt his'' wing."], "answer": "The bird hurt its wing.", "explanation": "*its* (no apostrophe) shows belonging."}]'::jsonb, 'published');
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('2503eb05-3b66-544c-95d1-45606baa7208', 'the-alphabet', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'The English alphabet', 'Learn the 26 letters, capital and small letters, and the five vowel letters.', 1, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('bacf7994-da31-5bee-800e-3ce6ee72f37a', '2503eb05-3b66-544c-95d1-45606baa7208', 'learn', 1, '26 letters', 'English has **26 letters**.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('bb80d92c-f0c7-57aa-a380-b6789e41e925', '2503eb05-3b66-544c-95d1-45606baa7208', 'see', 2, 'Examples', '- **A a**: apple
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('1c7d4f82-3efd-5446-b3b9-53cf3808ff4a', '2503eb05-3b66-544c-95d1-45606baa7208', 'try', 3, 'Try it', 'Say the vowels out loud: **a, e, i, o, u**.', '[{"id": "alpha-try-1", "type": "single_choice", "prompt": "Which letter is a vowel?", "options": ["b", "e", "t"], "answer": "e", "hint": "There are five vowels: a, e, i, o, u.", "explanation": "**e** is one of the five vowel letters."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('bdff3461-b716-58d8-86f6-13d7ece5dd98', '2503eb05-3b66-544c-95d1-45606baa7208', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "alpha-check-1", "type": "single_choice", "prompt": "How many letters are in the English alphabet?", "options": ["24", "26", "28"], "answer": "26", "explanation": "The English alphabet has 26 letters."}, {"id": "alpha-check-2", "type": "single_choice", "prompt": "Which sentence uses capital letters correctly?", "options": ["my name is ali.", "My name is Ali.", "my Name is ali."], "answer": "My name is Ali.", "explanation": "Use a capital at the start of a sentence and for names."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('02dea9b0-e595-5fb1-8923-18ff38c82788', 'basic-vocabulary-greetings', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'Basic vocabulary: greetings', 'Say hello, say goodbye and introduce yourself.', 2, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('4bb7ba32-193c-5186-ad74-056e73002f35', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'learn', 1, 'Hello and goodbye', 'We **greet** people when we meet them.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('0c492850-27a8-543c-87e1-cce06e4b81b7', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'see', 2, 'A short conversation', '**Sam:** Hello! My name is Sam.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('93ab4981-a3d1-5dd5-a946-fc3241ae1685', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'try', 3, 'Try it', 'Introduce yourself: *Hello, my name is ...*', '[{"id": "greet-try-1", "type": "single_choice", "prompt": "It is 8 in the morning. What do you say?", "options": ["Good night", "Good morning", "Goodbye"], "answer": "Good morning", "hint": "Think about the time of day.", "explanation": "*Good morning* is a greeting for the morning."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('6e394bd0-f2b4-525e-a5a4-828f5b29c2d8', '02dea9b0-e595-5fb1-8923-18ff38c82788', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "greet-check-1", "type": "single_choice", "prompt": "Someone says \"Nice to meet you.\" What is a good reply?", "options": ["Nice to meet you too.", "Goodbye.", "I am fine."], "answer": "Nice to meet you too.", "explanation": "We reply with the same words plus *too*."}, {"id": "greet-check-2", "type": "single_choice", "prompt": "Which word do we say when we leave?", "options": ["Hello", "Goodbye", "Hi"], "answer": "Goodbye", "explanation": "*Goodbye* is for leaving."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('841f1599-4d65-56ea-bd33-e5bb5e12372e', 'numbers-0-20', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'Numbers 0 to 20', 'Count from zero to twenty and spell the numbers.', 3, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('ce75f0fc-72b6-5f0a-bc7a-10c34af76459', '841f1599-4d65-56ea-bd33-e5bb5e12372e', 'learn', 1, 'Count to twenty', 'We use numbers to count things, say our age and give phone numbers.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('58e125d4-103a-5b54-a9a8-f9de5e53bee3', '841f1599-4d65-56ea-bd33-e5bb5e12372e', 'see', 2, 'Numbers in sentences', '- *I have **two** brothers.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('1ce9f68e-7b1c-5a76-82af-e06b5d5522dd', '841f1599-4d65-56ea-bd33-e5bb5e12372e', 'try', 3, 'Try it', 'Try it.', '[{"id": "num-try-1", "type": "single_choice", "prompt": "How do you write 8?", "options": ["eight", "eigth", "ate"], "answer": "eight", "hint": "It has a silent gh.", "explanation": "*eight* is the number 8. *ate* can sound the same, but it is the past of *eat*."}, {"id": "num-try-2", "type": "single_choice", "prompt": "What is 10 + 3?", "options": ["thirty", "thirteen", "three"], "answer": "thirteen", "hint": "Numbers 13 to 19 end in -teen.", "explanation": "10 + 3 = 13, *thirteen*. *Thirty* is 30."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('e877a1db-a97a-5e38-9c97-9b68d476362e', '841f1599-4d65-56ea-bd33-e5bb5e12372e', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "num-check-1", "type": "single_choice", "prompt": "Which number is \"fifteen\"?", "options": ["5", "15", "50"], "answer": "15", "explanation": "*Fifteen* is 15."}, {"id": "num-check-2", "type": "single_choice", "prompt": "How do you write 12?", "options": ["twelve", "twelf", "twenty"], "answer": "twelve", "explanation": "12 is *twelve*. *Twenty* is 20."}, {"id": "num-check-3", "type": "single_choice", "prompt": "What is 20 − 1?", "options": ["nineteen", "ninety", "nine"], "answer": "nineteen", "explanation": "20 − 1 = 19, *nineteen*."}, {"id": "num-check-4", "type": "single_choice", "prompt": "\"I have ___ hands.\"", "options": ["two", "too", "to"], "answer": "two", "explanation": "*Two* is the number 2. *Too* and *to* sound the same but mean different things."}, {"id": "num-check-5", "type": "single_choice", "prompt": "Which is the correct spelling?", "options": ["fourty", "fourteen", "forteen"], "answer": "fourteen", "explanation": "14 is *fourteen*: four + teen."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('11879be3-6d20-5711-a135-c63295a1d5ae', 'colours-and-classroom-objects', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '97b37b69-680b-53f2-a4ff-ee4402f45ea3', 'Colours and things in the classroom', 'Name colours and the things you use in class.', 4, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8727b3bb-bd5c-5c6d-920d-a4c38cd2e5c4', '11879be3-6d20-5711-a135-c63295a1d5ae', 'learn', 1, 'Colours and classroom words', '**Colours:** red, blue, green, yellow, black, white, brown, orange, pink, grey.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('b481b5b0-cd0f-500d-85b3-141ab851fae3', '11879be3-6d20-5711-a135-c63295a1d5ae', 'see', 2, 'Examples', '- *This is a **blue** book.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('848caa1e-4cc9-5cfc-899c-4a334b07f2e2', '11879be3-6d20-5711-a135-c63295a1d5ae', 'try', 3, 'Try it', 'Try it.', '[{"id": "col-try-1", "type": "single_choice", "prompt": "Which is correct?", "options": ["a pen red", "a red pen", "a reds pen"], "answer": "a red pen", "hint": "Where does the colour go?", "explanation": "The colour comes before the noun: *a red pen*."}, {"id": "col-try-2", "type": "single_choice", "prompt": "You sit on a ___.", "options": ["chair", "board", "window"], "answer": "chair", "explanation": "We sit on a *chair*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('3e934ad3-fbd9-54d7-8be8-e0f36c44564b', '11879be3-6d20-5711-a135-c63295a1d5ae', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "col-check-1", "type": "single_choice", "prompt": "The sky on a sunny day is usually ___.", "options": ["blue", "brown", "pink"], "answer": "blue", "explanation": "A clear sky is *blue*."}, {"id": "col-check-2", "type": "single_choice", "prompt": "You write with a ___.", "options": ["desk", "pen", "door"], "answer": "pen", "explanation": "We write with a *pen* or a *pencil*."}, {"id": "col-check-3", "type": "single_choice", "prompt": "Which is correct?", "options": ["two greens books", "two green books", "two books greens"], "answer": "two green books", "explanation": "Colours do not take -s: *two green books*."}, {"id": "col-check-4", "type": "single_choice", "prompt": "Snow is ___.", "options": ["white", "black", "orange"], "answer": "white", "explanation": "Snow is *white*."}, {"id": "col-check-5", "type": "single_choice", "prompt": "You carry your books in a ___.", "options": ["chair", "bag", "window"], "answer": "bag", "explanation": "We carry books in a *bag*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('19498871-224d-584a-bd4a-4fba1b8a125a', 'parts-of-speech', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'Parts of speech', 'Words have jobs: nouns, verbs, adjectives and more.', 5, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('532ba6d3-1bc8-5f07-9b6d-1052e86ac00d', '19498871-224d-584a-bd4a-4fba1b8a125a', 'learn', 1, 'Words have jobs', 'Every word has a **job** in a sentence.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('3d43bb19-84ef-5af9-b95b-015659e0c0fc', '19498871-224d-584a-bd4a-4fba1b8a125a', 'see', 2, 'Examples', '*The **happy** (adjective) **child** (noun) **runs** (verb) **quickly** (adverb).*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('edaa9c3f-0280-518c-a64d-d601f161a735', '19498871-224d-584a-bd4a-4fba1b8a125a', 'try', 3, 'Try it', 'Find the verb.', '[{"id": "pos-try-1", "type": "single_choice", "prompt": "In \"Birds sing\", which word is the verb?", "options": ["Birds", "sing"], "answer": "sing", "hint": "The verb is the action.", "explanation": "*sing* is the action, so it is the verb."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('19965829-ef60-5b53-a321-6d81007a791b', '19498871-224d-584a-bd4a-4fba1b8a125a', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "pos-check-1", "type": "single_choice", "prompt": "Which word is an adjective?", "options": ["table", "blue", "write"], "answer": "blue", "explanation": "*blue* describes a noun, so it is an adjective."}, {"id": "pos-check-2", "type": "single_choice", "prompt": "Which word is a noun?", "options": ["school", "quickly", "eat"], "answer": "school", "explanation": "*school* names a place, so it is a noun."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('fa28080c-61cc-5bad-94d4-529a605eafba', 'nouns-singular-plural', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'Nouns: one and many', 'Make plural nouns with -s and -es, and learn some special plurals.', 6, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('44249ada-1755-533c-a9b7-e29a50dd54fb', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'learn', 1, 'Singular and plural', '**Singular** means one. **Plural** means more than one.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('a9932a8a-5a32-5796-a90f-0bc4e3ec16f4', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'see', 2, 'Examples', '- one **cat**, two **cats**
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('50bec930-686e-5b97-a612-1caa8e00bf61', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'try', 3, 'Try it', 'Make the plural.', '[{"id": "noun-try-1", "type": "single_choice", "prompt": "One watch, two ...", "options": ["watchs", "watches"], "answer": "watches", "hint": "The word ends in -ch.", "explanation": "Nouns ending in -ch add -es: *watches*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('16aaa45b-055b-5544-a35a-1b2c74c43298', 'fa28080c-61cc-5bad-94d4-529a605eafba', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "noun-check-1", "type": "single_choice", "prompt": "What is the plural of \"child\"?", "options": ["childs", "children", "childes"], "answer": "children", "explanation": "*child* has a special plural: *children*."}, {"id": "noun-check-2", "type": "single_choice", "prompt": "What is the plural of \"pen\"?", "options": ["pens", "penes", "pen"], "answer": "pens", "explanation": "Most nouns add -s."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'pronouns', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'Pronouns', 'Use I, you, he, she, it, we and they instead of repeating nouns.', 7, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('29eafd70-089d-5391-99eb-b11b8728961b', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'learn', 1, 'Words that replace nouns', 'A **pronoun** takes the place of a noun, so we do not repeat it.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('530ae39c-bb29-53b5-aefe-1826785f1d11', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'see', 2, 'Examples', '*Anna is a doctor. **She** works in a hospital.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('4aab0ab1-7b9d-5bd1-9f2e-2ad5cc90cf90', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'try', 3, 'Try it', 'Choose the pronoun.', '[{"id": "pron-try-1", "type": "single_choice", "prompt": "Tom is tall. ... plays basketball.", "options": ["She", "He", "They"], "answer": "He", "hint": "Tom is one man.", "explanation": "For one man we use *he*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('3504e903-c736-52c2-ba2c-41c080c5e0be', '8f74417f-2ea5-57a6-8dc1-b7a8d452979b', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "pron-check-1", "type": "single_choice", "prompt": "The books are new. ... are on the table.", "options": ["It", "They", "We"], "answer": "They", "explanation": "For many things we use *they*."}, {"id": "pron-check-2", "type": "single_choice", "prompt": "My sister and I are students. ... study English.", "options": ["We", "They", "She"], "answer": "We", "explanation": "*My sister and I* includes me, so we use *we*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('852ee84f-a230-5a29-b79e-89c710b543fa', 'articles-a-an-the', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'A, an and the', 'Use a and an for one thing, and the for a thing we both know.', 8, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('b5475ad7-e84c-5419-acf7-6c4f9d84539f', '852ee84f-a230-5a29-b79e-89c710b543fa', 'learn', 1, 'A, an, the', '- Use **a** before a consonant **sound**: *a book, a cat, a university* (you-ni-ver-si-ty starts with a *y* sound).
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('fd6ae24c-19e4-536e-887d-bcc52f941241', '852ee84f-a230-5a29-b79e-89c710b543fa', 'see', 2, 'Examples', '*I have **a** dog and **a** cat. **The** dog is big and **the** cat is small.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('dacbc9d0-2495-5dcb-abcd-23ce411ccf87', '852ee84f-a230-5a29-b79e-89c710b543fa', 'try', 3, 'Try it', 'Try it.', '[{"id": "art-try-1", "type": "single_choice", "prompt": "I eat ___ apple every day.", "options": ["a", "an", "the"], "answer": "an", "hint": "Say the first sound of the word.", "explanation": "*Apple* starts with a vowel sound, so we say *an apple*."}, {"id": "art-try-2", "type": "single_choice", "prompt": "Please open ___ window. It is hot in here.", "options": ["a", "an", "the"], "answer": "the", "explanation": "We both know which window (the one in this room), so we use *the*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('574f5665-68c0-51fd-9e85-6c91127e05e0', '852ee84f-a230-5a29-b79e-89c710b543fa', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "art-check-1", "type": "single_choice", "prompt": "He is ___ teacher.", "options": ["a", "an", "the"], "answer": "a", "explanation": "*Teacher* starts with a consonant sound: *a teacher*."}, {"id": "art-check-2", "type": "single_choice", "prompt": "We waited for ___ hour.", "options": ["a", "an", "the"], "answer": "an", "explanation": "The *h* in *hour* is silent, so it starts with a vowel sound: *an hour*."}, {"id": "art-check-3", "type": "single_choice", "prompt": "She studies at ___ university in London.", "options": ["a", "an", "the"], "answer": "a", "explanation": "*University* starts with a *y* sound (a consonant sound): *a university*."}, {"id": "art-check-4", "type": "single_choice", "prompt": "I bought a shirt and a hat. ___ shirt is blue.", "options": ["A", "An", "The"], "answer": "The", "explanation": "We already talked about the shirt, so now we use *the*."}, {"id": "art-check-5", "type": "single_choice", "prompt": "___ moon is bright tonight.", "options": ["A", "An", "The"], "answer": "The", "explanation": "There is only one moon, so we use *the*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('07af16c5-a8dc-543d-811e-046326394468', 'this-that-these-those', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'd8107047-9780-5b15-b638-1478f05d58ca', 'This, that, these and those', 'Point to things near you and far from you.', 9, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('44096fb7-7d67-52a9-8285-30095c43e375', '07af16c5-a8dc-543d-811e-046326394468', 'learn', 1, 'Near and far', '| | near | far |
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('f5a83b81-f901-5ad9-ada2-70262711101f', '07af16c5-a8dc-543d-811e-046326394468', 'see', 2, 'Examples', '- ***This** is my phone.* (in my hand)
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('3060279b-bc0b-57bc-8947-f12c5080c02a', '07af16c5-a8dc-543d-811e-046326394468', 'try', 3, 'Try it', 'Try it.', '[{"id": "dem-try-1", "type": "single_choice", "prompt": "(The book is in your hand.) \"___ is my book.\"", "options": ["This", "These", "Those"], "answer": "This", "hint": "Is it one thing or many? Near or far?", "explanation": "One thing, near you: *this*."}, {"id": "dem-try-2", "type": "single_choice", "prompt": "(The cars are across the street.) \"___ cars are fast.\"", "options": ["This", "That", "Those"], "answer": "Those", "explanation": "Many things, far from you: *those*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8c11b308-c112-5996-9ff3-a18038d1d254', '07af16c5-a8dc-543d-811e-046326394468', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "dem-check-1", "type": "single_choice", "prompt": "(Many apples on your plate.) \"___ apples are sweet.\"", "options": ["These", "That", "This"], "answer": "These", "explanation": "Many things, near you: *these*."}, {"id": "dem-check-2", "type": "single_choice", "prompt": "(A house on the hill, far away.) \"___ house is very old.\"", "options": ["This", "That", "These"], "answer": "That", "explanation": "One thing, far away: *that*."}, {"id": "dem-check-3", "type": "single_choice", "prompt": "Which is correct?", "options": ["These is my bag.", "This are my bags.", "These are my bags."], "answer": "These are my bags.", "explanation": "*These* goes with plural nouns and *are*."}, {"id": "dem-check-4", "type": "single_choice", "prompt": "(Pointing at stars in the sky.) \"Look at ___ stars!\"", "options": ["this", "those", "that"], "answer": "those", "explanation": "Many things, far away: *those*."}, {"id": "dem-check-5", "type": "single_choice", "prompt": "(Holding one key.) \"Is ___ your key?\"", "options": ["this", "these", "those"], "answer": "this", "explanation": "One thing, near you: *this*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('c6641805-54ea-579c-9011-beb63a9f47dd', 'verb-to-be', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'db0627b0-e166-5c63-9f64-77cce74979fd', 'The verb to be: am, is, are', 'Say who you are, where you are from and how you feel.', 10, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('38de4981-0c41-5eb5-8e12-5f56c8101b16', 'c6641805-54ea-579c-9011-beb63a9f47dd', 'learn', 1, 'am, is, are', '| | to be | short form |
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('c8cb50da-9d75-5ae6-bf67-a73f3487b062', 'c6641805-54ea-579c-9011-beb63a9f47dd', 'see', 2, 'Examples', '- *I **am** Ali. I**''m** from Egypt.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('2c7d9ea4-a735-5375-ace9-6bcb6fb206fe', 'c6641805-54ea-579c-9011-beb63a9f47dd', 'try', 3, 'Try it', 'Try it.', '[{"id": "be-try-1", "type": "single_choice", "prompt": "They ___ my friends.", "options": ["am", "is", "are"], "answer": "are", "hint": "Look at the table: which verb goes with they?", "explanation": "*They* goes with *are*."}, {"id": "be-try-2", "type": "single_choice", "prompt": "Make a question: \"___ she your sister?\"", "options": ["Is", "Are", "Am"], "answer": "Is", "explanation": "Questions with *she* start with *Is*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('f7d0db00-ad1b-5d31-bc0a-12b6a3263005', 'c6641805-54ea-579c-9011-beb63a9f47dd', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "be-check-1", "type": "single_choice", "prompt": "I ___ hungry.", "options": ["am", "is", "are"], "answer": "am", "explanation": "*I* always goes with *am*."}, {"id": "be-check-2", "type": "single_choice", "prompt": "The weather ___ nice today.", "options": ["am", "is", "are"], "answer": "is", "explanation": "*The weather* is one thing (*it*), so we use *is*."}, {"id": "be-check-3", "type": "single_choice", "prompt": "Which sentence is negative?", "options": ["We are ready.", "We aren''t ready.", "Are we ready?"], "answer": "We aren''t ready.", "explanation": "*aren''t* = *are not*, so the sentence is negative."}, {"id": "be-check-4", "type": "single_choice", "prompt": "My parents ___ teachers.", "options": ["is", "are", "am"], "answer": "are", "explanation": "*My parents* = *they*, so we use *are*."}, {"id": "be-check-5", "type": "single_choice", "prompt": "\"Are you from Brazil?\" \"Yes, I ___.\"", "options": ["am", "are", "is"], "answer": "am", "explanation": "Short answer with *I*: *Yes, I am.*"}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('95f60bc8-72b0-5e2a-b300-209117d48a89', 'have-and-has', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'db0627b0-e166-5c63-9f64-77cce74979fd', 'Have and has', 'Talk about things you own, your family and your body.', 11, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('b6a817ef-3a85-52c3-8c7c-b5c0e8e64bfd', '95f60bc8-72b0-5e2a-b300-209117d48a89', 'learn', 1, 'have / has', '- **I / you / we / they** + **have**: *I have a bike.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('93acbed5-ba46-5a1e-b4b3-57b6e80606fc', '95f60bc8-72b0-5e2a-b300-209117d48a89', 'see', 2, 'Examples', '- *We **have** a big kitchen.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('2388ad20-a325-5a75-9a94-8f293f97ae58', '95f60bc8-72b0-5e2a-b300-209117d48a89', 'try', 3, 'Try it', 'Try it.', '[{"id": "have-try-1", "type": "single_choice", "prompt": "My sister ___ long hair.", "options": ["have", "has", "haves"], "answer": "has", "hint": "he / she / it use a different form.", "explanation": "*My sister* = *she*, so we use *has*."}, {"id": "have-try-2", "type": "single_choice", "prompt": "___ you have a pen?", "options": ["Do", "Does", "Are"], "answer": "Do", "explanation": "Questions with *you* use *Do*: *Do you have ...?*"}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('33ef9e62-eeb5-5c2a-9696-ae37d3641813', '95f60bc8-72b0-5e2a-b300-209117d48a89', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "have-check-1", "type": "single_choice", "prompt": "They ___ two children.", "options": ["have", "has", "having"], "answer": "have", "explanation": "*They* goes with *have*."}, {"id": "have-check-2", "type": "single_choice", "prompt": "It ___ four legs.", "options": ["have", "has", "is"], "answer": "has", "explanation": "*It* goes with *has*."}, {"id": "have-check-3", "type": "single_choice", "prompt": "Which is correct?", "options": ["He doesn''t has a phone.", "He don''t have a phone.", "He doesn''t have a phone."], "answer": "He doesn''t have a phone.", "explanation": "After *doesn''t*, use *have*."}, {"id": "have-check-4", "type": "single_choice", "prompt": "\"Does she have a car?\" \"No, she ___.\"", "options": ["doesn''t", "don''t", "isn''t"], "answer": "doesn''t", "explanation": "Short answer with *she*: *No, she doesn''t.*"}, {"id": "have-check-5", "type": "single_choice", "prompt": "I ___ a cold today.", "options": ["has", "have", "am"], "answer": "have", "explanation": "*I* goes with *have*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('e2342564-9784-5454-b519-8cc7338c40e9', 'present-simple-routines', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'db0627b0-e166-5c63-9f64-77cce74979fd', 'Present simple: daily routines', 'Say what you do every day, with -s for he, she and it.', 12, 14, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('09b14fd6-eb75-5923-b9bd-61c8e2ad9bb9', 'e2342564-9784-5454-b519-8cc7338c40e9', 'learn', 1, 'Habits and routines', 'We use the **present simple** for things we do often or always.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('dad66171-fcf2-572f-97b6-e41aa0be4c26', 'e2342564-9784-5454-b519-8cc7338c40e9', 'see', 2, 'A day in Mina''s life', '*Mina **gets up** at seven. She **has** breakfast and **goes** to work by bus. She **starts** work at nine. In the evening she **watches** TV or **reads**. She **doesn''t work** on Sundays.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('b78aa2a9-8673-5934-a56b-9362844adc65', 'e2342564-9784-5454-b519-8cc7338c40e9', 'try', 3, 'Try it', 'Try it.', '[{"id": "pres-try-1", "type": "single_choice", "prompt": "He ___ football on Saturdays.", "options": ["play", "plays", "playing"], "answer": "plays", "hint": "he / she / it add -s.", "explanation": "*He* needs *-s*: *plays*."}, {"id": "pres-try-2", "type": "single_choice", "prompt": "She ___ to bed at ten.", "options": ["gos", "goes", "go"], "answer": "goes", "explanation": "*go* becomes *goes* with he / she / it."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('d40a1162-d341-5841-a906-318db08be24a', 'e2342564-9784-5454-b519-8cc7338c40e9', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "pres-check-1", "type": "single_choice", "prompt": "My father ___ the news every morning.", "options": ["watch", "watchs", "watches"], "answer": "watches", "explanation": "Verbs ending in *-ch* add *-es*: *watches*."}, {"id": "pres-check-2", "type": "single_choice", "prompt": "We ___ English on Mondays.", "options": ["study", "studies", "studys"], "answer": "study", "explanation": "*We* has no *-s*: *study*."}, {"id": "pres-check-3", "type": "single_choice", "prompt": "Which is correct?", "options": ["She don''t like coffee.", "She doesn''t like coffee.", "She doesn''t likes coffee."], "answer": "She doesn''t like coffee.", "explanation": "Use *doesn''t* + base verb with *she*."}, {"id": "pres-check-4", "type": "single_choice", "prompt": "___ they live near here?", "options": ["Do", "Does", "Are"], "answer": "Do", "explanation": "Questions with *they* use *Do*."}, {"id": "pres-check-5", "type": "single_choice", "prompt": "Which sentence has the word in the right place?", "options": ["I walk always to school.", "I always walk to school.", "Always I walk school."], "answer": "I always walk to school.", "explanation": "*always* goes before the main verb: *I always walk*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('caca5015-fe2f-5cec-835f-4eb3ee0edcd2', 'days-and-time', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'db0627b0-e166-5c63-9f64-77cce74979fd', 'Days, months and telling the time', 'Say the day, the date and the time.', 13, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('9f1a7f99-0795-582e-be6e-a43821c00808', 'caca5015-fe2f-5cec-835f-4eb3ee0edcd2', 'learn', 1, 'Days, months and time', '**Days:** Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('b1f23a30-f247-5f0a-9bdd-b3059732113a', 'caca5015-fe2f-5cec-835f-4eb3ee0edcd2', 'see', 2, 'Examples', '- *My birthday is **in** June.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('a01d7056-f1de-5868-ba00-046446e28e3a', 'caca5015-fe2f-5cec-835f-4eb3ee0edcd2', 'try', 3, 'Try it', 'Try it.', '[{"id": "time-try-1", "type": "single_choice", "prompt": "The shop opens ___ 9 o''clock.", "options": ["on", "in", "at"], "answer": "at", "hint": "Look at the prepositions list.", "explanation": "We use *at* with clock times."}, {"id": "time-try-2", "type": "single_choice", "prompt": "Which day comes after Tuesday?", "options": ["Monday", "Wednesday", "Thursday"], "answer": "Wednesday", "explanation": "The order is Monday, Tuesday, **Wednesday** ..."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('1fea1339-dc37-5d60-8ea3-e1daadda2737', 'caca5015-fe2f-5cec-835f-4eb3ee0edcd2', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "time-check-1", "type": "single_choice", "prompt": "I was born ___ March.", "options": ["on", "in", "at"], "answer": "in", "explanation": "We use *in* with months."}, {"id": "time-check-2", "type": "single_choice", "prompt": "What is 4:30?", "options": ["half past four", "half past five", "quarter past four"], "answer": "half past four", "explanation": "4:30 is thirty minutes after four: *half past four*."}, {"id": "time-check-3", "type": "single_choice", "prompt": "Which is written correctly?", "options": ["see you on monday.", "See you on Monday.", "See you on MONDAY."], "answer": "See you on Monday.", "explanation": "Days start with a capital letter, and so does the first word."}, {"id": "time-check-4", "type": "single_choice", "prompt": "What is 10:45?", "options": ["quarter past ten", "quarter to eleven", "half past ten"], "answer": "quarter to eleven", "explanation": "10:45 is fifteen minutes before eleven: *quarter to eleven*."}, {"id": "time-check-5", "type": "single_choice", "prompt": "Which month comes before May?", "options": ["April", "June", "March"], "answer": "April", "explanation": "The order is ... March, **April**, May, June ..."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('2dbc4dc4-201b-53ae-8bc0-802271eef4b2', 'numbers-20-100', '92b6ddd3-64f7-519f-adb8-e85a817587e7', 'db0627b0-e166-5c63-9f64-77cce74979fd', 'Numbers 20 to 100 and prices', 'Count to one hundred, and say ages and prices.', 14, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('94ed1f50-44d2-5121-807a-55922222f45c', '2dbc4dc4-201b-53ae-8bc0-802271eef4b2', 'learn', 1, 'Tens and more', '**Tens:** 20 twenty, 30 thirty, 40 forty, 50 fifty, 60 sixty, 70 seventy, 80 eighty, 90 ninety, 100 one hundred.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('30128f11-7c0d-5107-9bb2-8085f8c7f684', '2dbc4dc4-201b-53ae-8bc0-802271eef4b2', 'see', 2, 'Prices and ages', '- *My grandmother is **seventy-two**.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('498030af-4403-5a83-a243-4adf8324fa62', '2dbc4dc4-201b-53ae-8bc0-802271eef4b2', 'try', 3, 'Try it', 'Try it.', '[{"id": "big-try-1", "type": "single_choice", "prompt": "How do you write 40?", "options": ["fourty", "forty", "fourteen"], "answer": "forty", "hint": "Different from four!", "explanation": "40 is *forty*, with no *u*."}, {"id": "big-try-2", "type": "single_choice", "prompt": "How do you write 67?", "options": ["sixty-seven", "sixty seven", "sixtyseven"], "answer": "sixty-seven", "explanation": "Use a hyphen: *sixty-seven*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('d9b7afae-6e4f-5eb5-93e8-7085fbb31c6e', '2dbc4dc4-201b-53ae-8bc0-802271eef4b2', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "big-check-1", "type": "single_choice", "prompt": "What is 50 + 5?", "options": ["fifteen", "fifty-five", "fifty"], "answer": "fifty-five", "explanation": "50 + 5 = 55, *fifty-five*."}, {"id": "big-check-2", "type": "single_choice", "prompt": "Which number is \"eighty-three\"?", "options": ["38", "83", "803"], "answer": "83", "explanation": "*Eighty-three* is 83."}, {"id": "big-check-3", "type": "single_choice", "prompt": "How do you say £7.20?", "options": ["seven pounds twenty", "seventy pounds two", "seven twenty pounds"], "answer": "seven pounds twenty", "explanation": "Say the pounds, then the pence: *seven pounds twenty*."}, {"id": "big-check-4", "type": "single_choice", "prompt": "What comes after ninety-nine?", "options": ["one hundred", "ninety-ten", "one thousand"], "answer": "one hundred", "explanation": "After 99 comes 100, *one hundred*."}, {"id": "big-check-5", "type": "single_choice", "prompt": "Which is 30?", "options": ["thirteen", "thirty", "three"], "answer": "thirty", "explanation": "30 is *thirty*. 13 is *thirteen*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('abb2d57f-e3ed-58a1-8be1-e5323cccd29d', 'family-words', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '96fc4244-4351-5fc7-9691-4c82cbd1f436', 'Family words', 'Name the people in your family.', 15, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('e85eac8c-78ae-5405-98f1-9e0aa1c4445c', 'abb2d57f-e3ed-58a1-8be1-e5323cccd29d', 'learn', 1, 'My family', '- **parents**: mother (mum) and father (dad)
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('de714572-a2ad-5886-aa56-29351f04ce61', 'abb2d57f-e3ed-58a1-8be1-e5323cccd29d', 'see', 2, 'Examples', '*This is my family. My **father** is a driver and my **mother** is a cook. I have one **sister**. My **grandparents** live with us. My **uncle**''s children are my **cousins**.*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('e01e6f96-1966-5207-a327-f9890157bd9b', 'abb2d57f-e3ed-58a1-8be1-e5323cccd29d', 'try', 3, 'Try it', 'Try it.', '[{"id": "fam-try-1", "type": "single_choice", "prompt": "Your mother''s mother is your ___.", "options": ["aunt", "grandmother", "sister"], "answer": "grandmother", "hint": "Think about grand-.", "explanation": "Your mother''s mother is your *grandmother*."}, {"id": "fam-try-2", "type": "single_choice", "prompt": "Which shows that the car belongs to Omar?", "options": ["Omar car", "Omars car", "Omar''s car"], "answer": "Omar''s car", "explanation": "Add *''s* to the owner''s name: *Omar''s car*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8d158f92-3c08-5462-9ec0-ffcd059c1617', 'abb2d57f-e3ed-58a1-8be1-e5323cccd29d', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "fam-check-1", "type": "single_choice", "prompt": "Your father''s brother is your ___.", "options": ["cousin", "uncle", "son"], "answer": "uncle", "explanation": "Your parent''s brother is your *uncle*."}, {"id": "fam-check-2", "type": "single_choice", "prompt": "A girl is her parents'' ___.", "options": ["son", "daughter", "aunt"], "answer": "daughter", "explanation": "A girl child is a *daughter*."}, {"id": "fam-check-3", "type": "single_choice", "prompt": "Your aunt''s children are your ___.", "options": ["cousins", "brothers", "parents"], "answer": "cousins", "explanation": "The children of your aunt or uncle are your *cousins*."}, {"id": "fam-check-4", "type": "single_choice", "prompt": "Your mother and father are your ___.", "options": ["grandparents", "parents", "children"], "answer": "parents", "explanation": "Mother + father = *parents*."}, {"id": "fam-check-5", "type": "single_choice", "prompt": "Which is correct?", "options": ["This is Anna''s bag.", "This is Annas bag.", "This is bag Anna."], "answer": "This is Anna''s bag.", "explanation": "Use *''s* to show the owner: *Anna''s bag*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('9b23b476-f7f6-5fc0-8d56-b24293266c09', 'possessive-adjectives', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '96fc4244-4351-5fc7-9691-4c82cbd1f436', 'My, your, his, her, our, their', 'Show who something belongs to.', 16, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('cc798f85-0aa3-5044-ac4a-6413d11f8594', '9b23b476-f7f6-5fc0-8d56-b24293266c09', 'learn', 1, 'Whose is it?', '| pronoun | possessive |
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('0aeeb4fa-cc10-5b3a-b746-e959be05ca0b', '9b23b476-f7f6-5fc0-8d56-b24293266c09', 'see', 2, 'Examples', '- *I like **my** new job.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('cca0cc74-dbcd-5fe3-88e0-c03d4969efbf', '9b23b476-f7f6-5fc0-8d56-b24293266c09', 'try', 3, 'Try it', 'Try it.', '[{"id": "poss-try-1", "type": "single_choice", "prompt": "Maria loves ___ cat.", "options": ["his", "her", "their"], "answer": "her", "hint": "Who is Maria: he, she or they?", "explanation": "Maria is *she*, so we use *her*."}, {"id": "poss-try-2", "type": "single_choice", "prompt": "The children are with ___ teacher.", "options": ["their", "there", "they''re"], "answer": "their", "explanation": "*Their* shows the teacher belongs to them. *There* is a place; *they''re* = *they are*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('54fa6150-008c-5e5d-b9f5-1ead72e47785', '9b23b476-f7f6-5fc0-8d56-b24293266c09', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "poss-check-1", "type": "single_choice", "prompt": "I can''t find ___ keys.", "options": ["my", "me", "I"], "answer": "my", "explanation": "Before a noun we use *my*."}, {"id": "poss-check-2", "type": "single_choice", "prompt": "John washes ___ car on Sundays.", "options": ["her", "his", "its"], "answer": "his", "explanation": "John is *he*, so *his*."}, {"id": "poss-check-3", "type": "single_choice", "prompt": "The dog wants ___ food.", "options": ["it''s", "its", "his"], "answer": "its", "explanation": "Belonging to *it* = *its* (no apostrophe)."}, {"id": "poss-check-4", "type": "single_choice", "prompt": "We visit ___ grandparents every summer.", "options": ["our", "we", "us"], "answer": "our", "explanation": "*We* → *our* before a noun."}, {"id": "poss-check-5", "type": "single_choice", "prompt": "Is this ___ coat, sir?", "options": ["you", "your", "you''re"], "answer": "your", "explanation": "*Your* shows it belongs to you. *You''re* = *you are*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('b4900f46-e919-512a-850a-e9b7e3a101d1', 'there-is-there-are', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '96fc4244-4351-5fc7-9691-4c82cbd1f436', 'There is and there are', 'Say what is in a place.', 17, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('de107ec6-0744-5806-9e1e-cb69fe757aa1', 'b4900f46-e919-512a-850a-e9b7e3a101d1', 'learn', 1, 'there is / there are', '- **There is** (*there''s*) + one thing: *There is a bank on this street.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('7f5689d3-fdf9-53d1-89d7-ed6c16462dbe', 'b4900f46-e919-512a-850a-e9b7e3a101d1', 'see', 2, 'My town', '*In my town **there is** a big market and **there are** two schools. **There isn''t** a cinema, but **there are** lots of cafés. **Is there** a hospital?* — *Yes, **there is**.*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8f1ab587-36c8-5aeb-83d0-a4e13e7a4f2d', 'b4900f46-e919-512a-850a-e9b7e3a101d1', 'try', 3, 'Try it', 'Try it.', '[{"id": "there-try-1", "type": "single_choice", "prompt": "___ a cat on the sofa.", "options": ["There is", "There are", "It are"], "answer": "There is", "hint": "One or more than one?", "explanation": "One cat: *There is*."}, {"id": "there-try-2", "type": "single_choice", "prompt": "___ any eggs in the fridge?", "options": ["Is there", "Are there", "There are"], "answer": "Are there", "explanation": "A question about more than one thing: *Are there ...?*"}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('733689d8-536d-5b7c-be05-b4d2d670b44d', 'b4900f46-e919-512a-850a-e9b7e3a101d1', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "there-check-1", "type": "single_choice", "prompt": "___ five people in my family.", "options": ["There is", "There are", "They are"], "answer": "There are", "explanation": "More than one: *There are*."}, {"id": "there-check-2", "type": "single_choice", "prompt": "There ___ a problem with my computer.", "options": ["is", "are", "be"], "answer": "is", "explanation": "One problem: *There is*."}, {"id": "there-check-3", "type": "single_choice", "prompt": "Which is the negative?", "options": ["There aren''t any trees.", "There are some trees.", "Are there any trees?"], "answer": "There aren''t any trees.", "explanation": "*aren''t* = *are not*, so it is negative."}, {"id": "there-check-4", "type": "single_choice", "prompt": "\"Is there a bank near here?\" \"Yes, ___.\"", "options": ["there is", "there are", "it is"], "answer": "there is", "explanation": "Short answer: *Yes, there is.*"}, {"id": "there-check-5", "type": "single_choice", "prompt": "There ___ two windows in this room.", "options": ["is", "are", "am"], "answer": "are", "explanation": "Two windows = more than one: *are*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('123e2287-2a81-52c3-b043-765eaecefcbc', 'prepositions-of-place', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '96fc4244-4351-5fc7-9691-4c82cbd1f436', 'In, on, under, next to', 'Say where things are.', 18, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('a55c07e3-5e0b-56e5-87d3-52e11ef9d62e', '123e2287-2a81-52c3-b043-765eaecefcbc', 'learn', 1, 'Where is it?', '- **in**: inside something: *in the box*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('9d3dd835-7363-5864-a504-86a674e0e140', '123e2287-2a81-52c3-b043-765eaecefcbc', 'see', 2, 'Examples', '- *The keys are **in** my bag.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('9beb126d-9fc2-5f91-b713-9720c91b08df', '123e2287-2a81-52c3-b043-765eaecefcbc', 'try', 3, 'Try it', 'Try it.', '[{"id": "prep-try-1", "type": "single_choice", "prompt": "The milk is ___ the fridge.", "options": ["in", "on", "under"], "answer": "in", "hint": "Is it inside or on top?", "explanation": "The milk is inside the fridge: *in*."}, {"id": "prep-try-2", "type": "single_choice", "prompt": "The picture is ___ the wall.", "options": ["in", "on", "under"], "answer": "on", "explanation": "Pictures hang on a surface: *on the wall*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('5b0347a7-da6d-503a-a9c8-85beea8d6f82', '123e2287-2a81-52c3-b043-765eaecefcbc', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "prep-check-1", "type": "single_choice", "prompt": "The shoes are ___ the bed. You can''t see them.", "options": ["on", "under", "next to"], "answer": "under", "explanation": "Below the bed: *under*."}, {"id": "prep-check-2", "type": "single_choice", "prompt": "B is ___ A and C.", "options": ["between", "behind", "in"], "answer": "between", "explanation": "In the middle of two things: *between*."}, {"id": "prep-check-3", "type": "single_choice", "prompt": "My house is ___ the school. It is right at its side.", "options": ["next to", "in", "under"], "answer": "next to", "explanation": "At the side of: *next to*."}, {"id": "prep-check-4", "type": "single_choice", "prompt": "Put the plates ___ the table, please.", "options": ["on", "in", "under"], "answer": "on", "explanation": "On top of the table: *on*."}, {"id": "prep-check-5", "type": "single_choice", "prompt": "The car is ___ the house. You can see it from the front door.", "options": ["behind", "in front of", "under"], "answer": "in front of", "explanation": "If you see it from the front door, it is *in front of* the house."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('5db1bb94-e4ee-5150-afb7-639cb9210b64', 'can-for-ability', '92b6ddd3-64f7-519f-adb8-e85a817587e7', '96fc4244-4351-5fc7-9691-4c82cbd1f436', 'Can and can''t', 'Say what you are able to do.', 19, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('d4d685b5-92fc-5e02-a6bb-265c77d9a7b6', '5db1bb94-e4ee-5150-afb7-639cb9210b64', 'learn', 1, 'can / can''t', '**can** + base verb, the same for everyone: *I can swim. She can swim. They can swim.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('5fbf3522-5811-5468-bf42-5d81742d6f40', '5db1bb94-e4ee-5150-afb7-639cb9210b64', 'see', 2, 'Examples', '- *My little brother **can** read now.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('08a4e11d-7e87-5037-9fa4-a27acd454dd3', '5db1bb94-e4ee-5150-afb7-639cb9210b64', 'try', 3, 'Try it', 'Try it.', '[{"id": "can-try-1", "type": "single_choice", "prompt": "She ___ ride a bike.", "options": ["can", "cans", "can to"], "answer": "can", "hint": "can is the same for everyone.", "explanation": "*can* never takes *-s* or *to*."}, {"id": "can-try-2", "type": "single_choice", "prompt": "\"Can you swim?\" \"No, I ___.\"", "options": ["can''t", "don''t", "am not"], "answer": "can''t", "explanation": "Short answer: *No, I can''t.*"}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('1caa2944-8004-54e7-ad95-7c803b9515aa', '5db1bb94-e4ee-5150-afb7-639cb9210b64', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "can-check-1", "type": "single_choice", "prompt": "Which is correct?", "options": ["He can plays tennis.", "He can play tennis.", "He can to play tennis."], "answer": "He can play tennis.", "explanation": "*can* + base verb: *can play*."}, {"id": "can-check-2", "type": "single_choice", "prompt": "Birds ___ fly, but fish can''t.", "options": ["can", "can''t", "cans"], "answer": "can", "explanation": "Birds are able to fly: *can*."}, {"id": "can-check-3", "type": "single_choice", "prompt": "I ___ open this jar. It''s too tight.", "options": ["can", "can''t", "do"], "answer": "can''t", "explanation": "Not able: *can''t*."}, {"id": "can-check-4", "type": "single_choice", "prompt": "Make a question: \"___ you help me?\"", "options": ["Do", "Can", "Are"], "answer": "Can", "explanation": "Ask about ability or help with *Can you ...?*"}, {"id": "can-check-5", "type": "single_choice", "prompt": "Babies ___ walk when they are born.", "options": ["can", "can''t", "cans"], "answer": "can''t", "explanation": "Newborn babies are not able to walk: *can''t*."}]'::jsonb);
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('f324823d-3168-58c7-9946-dd69ffd6d3da', 'l2-u1-past-events', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'Unit 1: Past events', 'Talk about what happened: was, were and the past simple.', 1, '[{"id": "u21-t1", "type": "single_choice", "prompt": "We ___ very tired after the game.", "options": ["was", "were", "did"], "answer": "were", "explanation": "*We* → *were*."}, {"id": "u21-t2", "type": "single_choice", "prompt": "She ___ the window because it was hot.", "options": ["opened", "opend", "open"], "answer": "opened", "explanation": "Regular past: *opened*."}, {"id": "u21-t3", "type": "single_choice", "prompt": "I ___ my keys at home.", "options": ["leaved", "left", "leave"], "answer": "left", "explanation": "The past of *leave* is *left*."}, {"id": "u21-t4", "type": "single_choice", "prompt": "They ___ the answer.", "options": ["didn''t know", "didn''t knew", "not knew"], "answer": "didn''t know", "explanation": "*didn''t* + base verb."}, {"id": "u21-t5", "type": "single_choice", "prompt": "I finished university three years ___.", "options": ["ago", "last", "before"], "answer": "ago", "explanation": "*three years ago*."}, {"id": "u21-t6", "type": "single_choice", "prompt": "___ you see the news?", "options": ["Did", "Were", "Do"], "answer": "Did", "explanation": "Past simple question: *Did you see ...?*"}]'::jsonb, 'published');
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('36c7899a-53b8-54f1-a9b2-bd2e42c04389', 'l2-u2-now-and-next', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'Unit 2: Now and next', 'Talk about now, your plans and the future.', 2, '[{"id": "u22-t1", "type": "single_choice", "prompt": "Shh! I ___ to the radio.", "options": ["listen", "am listening", "listens"], "answer": "am listening", "explanation": "Now: present continuous."}, {"id": "u22-t2", "type": "single_choice", "prompt": "She ___ tea. She prefers coffee.", "options": ["doesn''t like", "isn''t liking", "don''t like"], "answer": "doesn''t like", "explanation": "*like* is not used with -ing; *she* → *doesn''t*."}, {"id": "u22-t3", "type": "single_choice", "prompt": "We have the tickets. We ___ see the show on Friday.", "options": ["are going to", "will to", "going"], "answer": "are going to", "explanation": "A plan already made: *are going to*."}, {"id": "u22-t4", "type": "single_choice", "prompt": "\"It''s dark in here.\" \"I ___ turn on the light.\"", "options": ["''ll", "''m going", "turn"], "answer": "''ll", "explanation": "A decision made now: *I''ll*."}, {"id": "u22-t5", "type": "single_choice", "prompt": "The film starts ___ ten minutes.", "options": ["in", "ago", "next"], "answer": "in", "explanation": "*in ten minutes* = from now."}, {"id": "u22-t6", "type": "single_choice", "prompt": "Which is correct?", "options": ["He is running every morning.", "He runs every morning.", "He run every morning."], "answer": "He runs every morning.", "explanation": "*every morning* = habit: *He runs*."}]'::jsonb, 'published');
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('1af4f4a1-edbe-592f-afce-b0eecf79229a', 'l2-u3-describing-and-comparing', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'Unit 3: Describing and comparing', 'Compare things, say how people do things, and talk about quantity.', 3, '[{"id": "u23-t1", "type": "single_choice", "prompt": "A plane is ___ than a car.", "options": ["fast", "faster", "fastest"], "answer": "faster", "explanation": "Two things: comparative *faster*."}, {"id": "u23-t2", "type": "single_choice", "prompt": "It''s ___ restaurant in the city.", "options": ["the best", "the better", "best than"], "answer": "the best", "explanation": "Superlative: *the best*."}, {"id": "u23-t3", "type": "single_choice", "prompt": "Please drive ___.", "options": ["slow", "slowly", "slowlly"], "answer": "slowly", "explanation": "Adverb: *slowly*."}, {"id": "u23-t4", "type": "single_choice", "prompt": "Can you give me ___ information?", "options": ["an", "some", "many"], "answer": "some", "explanation": "*information* is uncountable: *some*."}, {"id": "u23-t5", "type": "single_choice", "prompt": "How ___ people came to the meeting?", "options": ["much", "many", "lot"], "answer": "many", "explanation": "*people* is countable plural: *how many*."}, {"id": "u23-t6", "type": "single_choice", "prompt": "This chair is ___ than that one.", "options": ["more comfortable", "comfortabler", "most comfortable"], "answer": "more comfortable", "explanation": "Long adjective: *more comfortable*."}]'::jsonb, 'published');
insert into public.units (id, slug, learning_level_id, title, summary, sort_order, test_items, status) values ('89ce1393-96f5-54c6-81dd-63ccbbe8f704', 'l2-u4-everyday-english', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'Unit 4: Everyday English', 'Use pronouns, talk about rules and advice, and join ideas into a short story.', 4, '[{"id": "u24-t1", "type": "single_choice", "prompt": "My grandmother lives with ___.", "options": ["we", "us", "our"], "answer": "us", "explanation": "Object after *with*: *us*."}, {"id": "u24-t2", "type": "single_choice", "prompt": "You ___ park here. It''s not allowed.", "options": ["mustn''t", "don''t have to", "should"], "answer": "mustn''t", "explanation": "Not allowed: *mustn''t*."}, {"id": "u24-t3", "type": "single_choice", "prompt": "You have a headache. You ___ rest.", "options": ["should", "shouldn''t", "should to"], "answer": "should", "explanation": "Advice: *should*."}, {"id": "u24-t4", "type": "single_choice", "prompt": "I didn''t go out ___ it was very cold.", "options": ["so", "because", "but"], "answer": "because", "explanation": "Reason: *because*."}, {"id": "u24-t5", "type": "single_choice", "prompt": "___, we packed our bags. Then we drove to the airport.", "options": ["Finally", "First", "After that"], "answer": "First", "explanation": "First event: *First*."}, {"id": "u24-t6", "type": "single_choice", "prompt": "He ___ wear glasses to read. He can''t see well without them.", "options": ["has to", "have to", "must to"], "answer": "has to", "explanation": "*he* → *has to*."}]'::jsonb, 'published');
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('539627b6-f99b-5916-9237-5a3ce53045be', 'past-was-were', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'f324823d-3168-58c7-9946-dd69ffd6d3da', 'Past of to be: was and were', 'Talk about where people were and how things were.', 1, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8a45ebc8-b4a0-54d8-bf8f-e9046b236248', '539627b6-f99b-5916-9237-5a3ce53045be', 'learn', 1, 'was / were', '| | past of *to be* |
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('520e7f95-a01d-58a4-bc22-1b4f54185dc7', '539627b6-f99b-5916-9237-5a3ce53045be', 'see', 2, 'Examples', '- *I **was** at the doctor''s yesterday.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8838151d-4a6c-544a-a3de-120abb549f82', '539627b6-f99b-5916-9237-5a3ce53045be', 'try', 3, 'Try it', 'Try it.', '[{"id": "was-try-1", "type": "single_choice", "prompt": "My grandparents ___ farmers.", "options": ["was", "were", "are been"], "answer": "were", "hint": "they → ?", "explanation": "*My grandparents* = *they*, so *were*."}, {"id": "was-try-2", "type": "single_choice", "prompt": "___ the shop open yesterday?", "options": ["Was", "Were", "Did"], "answer": "Was", "explanation": "*The shop* = *it*, so the question starts with *Was*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('5e4616cc-78fe-57ad-bc00-7e6c8cc40868', '539627b6-f99b-5916-9237-5a3ce53045be', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "was-check-1", "type": "single_choice", "prompt": "It ___ very hot last summer.", "options": ["was", "were", "is"], "answer": "was", "explanation": "*It* + past = *was*."}, {"id": "was-check-2", "type": "single_choice", "prompt": "You ___ late this morning.", "options": ["was", "were", "be"], "answer": "were", "explanation": "*You* always goes with *were*."}, {"id": "was-check-3", "type": "single_choice", "prompt": "Which is the negative?", "options": ["They weren''t happy.", "They were happy.", "Were they happy?"], "answer": "They weren''t happy.", "explanation": "*weren''t* = *were not*."}, {"id": "was-check-4", "type": "single_choice", "prompt": "\"Was Sam at the party?\" \"No, he ___.\"", "options": ["wasn''t", "weren''t", "didn''t"], "answer": "wasn''t", "explanation": "Short answer with *he*: *No, he wasn''t.*"}, {"id": "was-check-5", "type": "single_choice", "prompt": "Where ___ you last night?", "options": ["was", "were", "did"], "answer": "were", "explanation": "*you* → *were*: *Where were you?*"}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('0813168b-b760-5aa2-9a91-c2af98e965f0', 'past-simple-regular', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'f324823d-3168-58c7-9946-dd69ffd6d3da', 'Past simple: regular verbs', 'Add -ed to talk about finished actions.', 2, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('b855417a-6b03-5d22-88f6-a503b16016fe', '0813168b-b760-5aa2-9a91-c2af98e965f0', 'learn', 1, 'Finished actions', 'We use the **past simple** for actions that finished in the past.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8aa90e92-5d90-530c-a876-56e4b51f7ce9', '0813168b-b760-5aa2-9a91-c2af98e965f0', 'see', 2, 'Examples', '*Last weekend I **visited** my aunt. We **cooked** lunch and **watched** a film. On Sunday it **rained**, so I **stayed** at home and **studied**.*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('19c5459d-5c88-57fd-997c-e42c649740ad', '0813168b-b760-5aa2-9a91-c2af98e965f0', 'try', 3, 'Try it', 'Try it.', '[{"id": "reg-try-1", "type": "single_choice", "prompt": "Yesterday I ___ my room.", "options": ["clean", "cleaned", "cleaning"], "answer": "cleaned", "hint": "Add -ed.", "explanation": "Past simple: *clean + ed = cleaned*."}, {"id": "reg-try-2", "type": "single_choice", "prompt": "What is the past of \"try\"?", "options": ["tryed", "tried", "trys"], "answer": "tried", "explanation": "Consonant + *y* → *ied*: *tried*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('0552fe72-4b7e-5696-9cc8-d56eba3cb717', '0813168b-b760-5aa2-9a91-c2af98e965f0', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "reg-check-1", "type": "single_choice", "prompt": "She ___ in Rome for two years.", "options": ["live", "lived", "liveed"], "answer": "lived", "explanation": "*live* ends in *e*, so add *d*: *lived*."}, {"id": "reg-check-2", "type": "single_choice", "prompt": "The bus ___ suddenly.", "options": ["stoped", "stopped", "stopt"], "answer": "stopped", "explanation": "*stop* doubles the *p*: *stopped*."}, {"id": "reg-check-3", "type": "single_choice", "prompt": "We ___ football after school.", "options": ["played", "plaied", "plays"], "answer": "played", "explanation": "Vowel + *y*: just add *ed*: *played*."}, {"id": "reg-check-4", "type": "single_choice", "prompt": "Which sentence is in the past?", "options": ["I walk to work.", "I walked to work.", "I am walking to work."], "answer": "I walked to work.", "explanation": "*walked* is past simple."}, {"id": "reg-check-5", "type": "single_choice", "prompt": "He ___ for the exam all night.", "options": ["studyed", "studied", "studies"], "answer": "studied", "explanation": "*study* → *studied*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('27a43244-57af-5785-82d3-bcfc89b1b4d5', 'past-simple-irregular', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'f324823d-3168-58c7-9946-dd69ffd6d3da', 'Past simple: irregular verbs', 'Learn common verbs that do not use -ed.', 3, 14, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('716f0de5-2913-5b7a-9632-c88c5147be28', '27a43244-57af-5785-82d3-bcfc89b1b4d5', 'learn', 1, 'Irregular verbs', 'Many common verbs have a special past form. Learn them by heart.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('2b46e9f6-4ca6-51b6-a89b-74dfe05912de', '27a43244-57af-5785-82d3-bcfc89b1b4d5', 'see', 2, 'A story', '*On Saturday I **went** to the market. I **saw** my friend Leo there. We **bought** some fruit and **had** coffee. Then we **took** the bus home. Leo **said** it **was** a great day.*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8d3a860d-1e35-52a4-838a-30a6c02a8e7b', '27a43244-57af-5785-82d3-bcfc89b1b4d5', 'try', 3, 'Try it', 'Try it.', '[{"id": "irr-try-1", "type": "single_choice", "prompt": "Last year we ___ to Spain.", "options": ["goed", "went", "gone"], "answer": "went", "hint": "It is irregular.", "explanation": "The past of *go* is *went*."}, {"id": "irr-try-2", "type": "single_choice", "prompt": "I ___ a letter to my grandmother.", "options": ["writed", "wrote", "write"], "answer": "wrote", "explanation": "The past of *write* is *wrote*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('ac13c8c8-041b-5dfe-abd3-286942d408a4', '27a43244-57af-5785-82d3-bcfc89b1b4d5', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "irr-check-1", "type": "single_choice", "prompt": "She ___ a new phone last week.", "options": ["buyed", "bought", "buys"], "answer": "bought", "explanation": "The past of *buy* is *bought*."}, {"id": "irr-check-2", "type": "single_choice", "prompt": "We ___ pizza for dinner.", "options": ["ate", "eated", "eat"], "answer": "ate", "explanation": "The past of *eat* is *ate*."}, {"id": "irr-check-3", "type": "single_choice", "prompt": "They ___ home very late.", "options": ["comed", "came", "come"], "answer": "came", "explanation": "The past of *come* is *came*."}, {"id": "irr-check-4", "type": "single_choice", "prompt": "I ___ a strange noise in the night.", "options": ["heard", "heared", "hear"], "answer": "heard", "explanation": "The past of *hear* is *heard*."}, {"id": "irr-check-5", "type": "single_choice", "prompt": "He ___ that he was busy.", "options": ["sayed", "said", "says"], "answer": "said", "explanation": "The past of *say* is *said*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('b15a5bab-3b65-5ebc-b5c7-ecdb4b7bab3b', 'past-simple-questions-negatives', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'f324823d-3168-58c7-9946-dd69ffd6d3da', 'Past simple: questions and negatives', 'Use did and didn''t to ask and say no about the past.', 4, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('76a1d8f6-7dfc-5aaf-965f-893f7e102ca3', 'b15a5bab-3b65-5ebc-b5c7-ecdb4b7bab3b', 'learn', 1, 'did / didn''t', '- **Negative:** *didn''t* + base verb: *I **didn''t go** to work.* (not *didn''t went*)
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('ff2bd9dd-5cb7-5a80-b67b-3e2fa80c63cc', 'b15a5bab-3b65-5ebc-b5c7-ecdb4b7bab3b', 'see', 2, 'Examples', '- ***Did** you **enjoy** the concert?* — *Yes, I **did**.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('f2bd6bbd-a99c-55c9-85f2-f6c40711130b', 'b15a5bab-3b65-5ebc-b5c7-ecdb4b7bab3b', 'try', 3, 'Try it', 'Try it.', '[{"id": "dq-try-1", "type": "single_choice", "prompt": "I ___ my homework yesterday.", "options": ["didn''t finish", "didn''t finished", "not finished"], "answer": "didn''t finish", "hint": "didn''t + base verb", "explanation": "After *didn''t*, use the base verb: *didn''t finish*."}, {"id": "dq-try-2", "type": "single_choice", "prompt": "___ you call your mother?", "options": ["Did", "Do", "Were"], "answer": "Did", "explanation": "Past simple questions start with *Did*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('52fb9a90-739c-56c7-8926-a49fa90569cf', 'b15a5bab-3b65-5ebc-b5c7-ecdb4b7bab3b', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "dq-check-1", "type": "single_choice", "prompt": "Where ___ you go on holiday?", "options": ["did", "were", "do"], "answer": "did", "explanation": "*Where did you go?*"}, {"id": "dq-check-2", "type": "single_choice", "prompt": "Which is correct?", "options": ["Did she came?", "Did she come?", "Did she comes?"], "answer": "Did she come?", "explanation": "After *Did*, use the base verb."}, {"id": "dq-check-3", "type": "single_choice", "prompt": "\"Did they win?\" \"No, they ___.\"", "options": ["didn''t", "weren''t", "don''t"], "answer": "didn''t", "explanation": "Short answer: *No, they didn''t.*"}, {"id": "dq-check-4", "type": "single_choice", "prompt": "He ___ at home last night.", "options": ["didn''t be", "wasn''t", "not was"], "answer": "wasn''t", "explanation": "With *be* we use *wasn''t*, not *didn''t*."}, {"id": "dq-check-5", "type": "single_choice", "prompt": "What ___ you have for breakfast?", "options": ["did", "was", "do"], "answer": "did", "explanation": "*What did you have ...?*"}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('d7714599-223e-54c4-80cb-d0ed67d0fdfb', 'past-time-expressions', 'd17b31cb-2ed4-5377-b203-17024625bd0e', 'f324823d-3168-58c7-9946-dd69ffd6d3da', 'Yesterday, last week, two days ago', 'Say when something happened.', 5, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('06e38991-a657-5e1b-bf1e-0821f7865798', 'd7714599-223e-54c4-80cb-d0ed67d0fdfb', 'learn', 1, 'When did it happen?', '- **yesterday** / **yesterday morning**
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('ce466830-9b06-533c-bb21-f3b52a43044a', 'd7714599-223e-54c4-80cb-d0ed67d0fdfb', 'see', 2, 'Examples', '- *I started this job **three months ago**.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('605b6f34-a47a-5abc-a2d5-f9ef8cbfa918', 'd7714599-223e-54c4-80cb-d0ed67d0fdfb', 'try', 3, 'Try it', 'Try it.', '[{"id": "ptx-try-1", "type": "single_choice", "prompt": "I met her two years ___.", "options": ["ago", "last", "before"], "answer": "ago", "hint": "Which word comes after the time?", "explanation": "Time + *ago*: *two years ago*."}, {"id": "ptx-try-2", "type": "single_choice", "prompt": "We moved here ___ year.", "options": ["last", "the last", "ago"], "answer": "last", "explanation": "*last year* (no *the*)."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('98c77be9-7eac-5acf-80c6-b7843411c235', 'd7714599-223e-54c4-80cb-d0ed67d0fdfb', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "ptx-check-1", "type": "single_choice", "prompt": "The class finished ten minutes ___.", "options": ["ago", "last", "yesterday"], "answer": "ago", "explanation": "*ten minutes ago*."}, {"id": "ptx-check-2", "type": "single_choice", "prompt": "I phoned you ___ night.", "options": ["yesterday", "last", "ago"], "answer": "last", "explanation": "*last night*. (We say *yesterday evening*, but *last night*.)"}, {"id": "ptx-check-3", "type": "single_choice", "prompt": "He finished school ___ 2015.", "options": ["on", "in", "at"], "answer": "in", "explanation": "*in* + year."}, {"id": "ptx-check-4", "type": "single_choice", "prompt": "The parcel arrived ___ Friday.", "options": ["on", "in", "ago"], "answer": "on", "explanation": "*on* + day."}, {"id": "ptx-check-5", "type": "single_choice", "prompt": "Which sentence is correct?", "options": ["I saw him the last week.", "I saw him last week.", "I saw him week ago."], "answer": "I saw him last week.", "explanation": "*last week*, with no *the*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('94e37048-3870-52ab-b5a9-c01ecc5b9f8a', 'present-continuous-now', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '36c7899a-53b8-54f1-a9b2-bd2e42c04389', 'Present continuous: happening now', 'Say what people are doing at the moment.', 6, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('ed4ff54d-ce5c-536c-8882-14da0c4ed524', '94e37048-3870-52ab-b5a9-c01ecc5b9f8a', 'learn', 1, 'am / is / are + -ing', 'We use the **present continuous** for actions happening **now** or around now.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('ed51bd57-22b2-58f8-84c9-871793f5fe62', '94e37048-3870-52ab-b5a9-c01ecc5b9f8a', 'see', 2, 'Look out of the window', '*It **is raining**. A man **is running** for the bus. Two children **are playing** in the park. My neighbour **isn''t working** today: she **is sitting** in her garden.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('fb08b9ba-bbd5-5f5a-bd8e-1aa956698916', '94e37048-3870-52ab-b5a9-c01ecc5b9f8a', 'try', 3, 'Try it', 'Try it.', '[{"id": "pc-try-1", "type": "single_choice", "prompt": "Be quiet! The baby ___.", "options": ["sleeps", "is sleeping", "sleeping"], "answer": "is sleeping", "hint": "am / is / are + -ing", "explanation": "Happening now: *is sleeping*."}, {"id": "pc-try-2", "type": "single_choice", "prompt": "What is the -ing form of \"swim\"?", "options": ["swiming", "swimming", "swimeing"], "answer": "swimming", "explanation": "Short verb, one vowel + one consonant: double it: *swimming*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('cabc0f9a-be88-50bc-8914-8e33dedff5fb', '94e37048-3870-52ab-b5a9-c01ecc5b9f8a', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "pc-check-1", "type": "single_choice", "prompt": "They ___ TV right now.", "options": ["watch", "are watching", "watching"], "answer": "are watching", "explanation": "*They* + *are* + *watching*."}, {"id": "pc-check-2", "type": "single_choice", "prompt": "I ___ dinner at the moment.", "options": ["am making", "am makeing", "make"], "answer": "am making", "explanation": "*make* drops the *e*: *making*."}, {"id": "pc-check-3", "type": "single_choice", "prompt": "Which is a question?", "options": ["Is she working?", "She is working.", "She isn''t working."], "answer": "Is she working?", "explanation": "Questions start with *Is / Are*."}, {"id": "pc-check-4", "type": "single_choice", "prompt": "Listen! Someone ___ at the door.", "options": ["knocks", "is knocking", "knocked"], "answer": "is knocking", "explanation": "*Listen!* means now: *is knocking*."}, {"id": "pc-check-5", "type": "single_choice", "prompt": "He ___ today. He is at home.", "options": ["isn''t working", "doesn''t working", "not work"], "answer": "isn''t working", "explanation": "Negative: *isn''t* + *-ing*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('ed6a2556-da51-5f2d-b680-4b0b05368e8e', 'present-simple-vs-continuous', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '36c7899a-53b8-54f1-a9b2-bd2e42c04389', 'Present simple or present continuous?', 'Choose between habits and things happening now.', 7, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('2c12f50c-617c-54fb-82a1-e53ea273edcb', 'ed6a2556-da51-5f2d-b680-4b0b05368e8e', 'learn', 1, 'Habit or now?', '- **Present simple**: habits, routines and facts: *I **drink** coffee every morning.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('44557e5d-3490-57d4-97cf-d6ef3ebf8898', 'ed6a2556-da51-5f2d-b680-4b0b05368e8e', 'see', 2, 'Examples', '- *Ali usually **walks** to work, but today he**''s taking** the bus.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('d149af36-cf86-53cd-bef6-ef0f2f04a68f', 'ed6a2556-da51-5f2d-b680-4b0b05368e8e', 'try', 3, 'Try it', 'Try it.', '[{"id": "svc-try-1", "type": "single_choice", "prompt": "She ___ to the gym every Tuesday.", "options": ["goes", "is going", "go"], "answer": "goes", "hint": "Look for the clue word.", "explanation": "*every Tuesday* = a habit: present simple."}, {"id": "svc-try-2", "type": "single_choice", "prompt": "Look! It ___.", "options": ["snows", "is snowing", "snow"], "answer": "is snowing", "explanation": "*Look!* = now: present continuous."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('4727ded3-44a8-53c6-9ffd-75271037fa9b', 'ed6a2556-da51-5f2d-b680-4b0b05368e8e', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "svc-check-1", "type": "single_choice", "prompt": "I ___ what you mean.", "options": ["understand", "am understanding", "understanding"], "answer": "understand", "explanation": "*understand* is not normally used with -ing."}, {"id": "svc-check-2", "type": "single_choice", "prompt": "My brother ___ for an exam this week.", "options": ["studies", "is studying", "study"], "answer": "is studying", "explanation": "*this week* = around now: present continuous."}, {"id": "svc-check-3", "type": "single_choice", "prompt": "The sun ___ in the east.", "options": ["rises", "is rising", "rising"], "answer": "rises", "explanation": "A fact: present simple."}, {"id": "svc-check-4", "type": "single_choice", "prompt": "\"Where''s Mum?\" \"She ___ in the garden.\"", "options": ["works", "is working", "work"], "answer": "is working", "explanation": "Happening now: present continuous."}, {"id": "svc-check-5", "type": "single_choice", "prompt": "We never ___ meat.", "options": ["eat", "are eating", "eats"], "answer": "eat", "explanation": "*never* = a habit: present simple. *We* has no *-s*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('50afeb3e-bba3-5898-9e4b-ca6f1609a699', 'going-to-plans', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '36c7899a-53b8-54f1-a9b2-bd2e42c04389', 'Going to: plans and intentions', 'Talk about things you have decided to do.', 8, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('a2e54281-ff7a-5d2b-af48-5bb6166dd498', '50afeb3e-bba3-5898-9e4b-ca6f1609a699', 'learn', 1, 'be going to + verb', 'Use **be going to** for plans you have already made, and for things we can see are going to happen.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('f947793b-1979-5163-88fe-3d7e648efac6', '50afeb3e-bba3-5898-9e4b-ca6f1609a699', 'see', 2, 'Plans for the summer', '*This summer **I''m going to** learn to drive. My sister **is going to** work in a hotel. We **aren''t going to** travel abroad, but we **are going to** visit the coast for a weekend.*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('acb504c1-a622-517e-bad3-3bfd8464fac3', '50afeb3e-bba3-5898-9e4b-ca6f1609a699', 'try', 3, 'Try it', 'Try it.', '[{"id": "gt-try-1", "type": "single_choice", "prompt": "We ___ paint the kitchen next weekend.", "options": ["are going to", "going to", "are go to"], "answer": "are going to", "hint": "be + going to", "explanation": "*We* + *are going to* + verb."}, {"id": "gt-try-2", "type": "single_choice", "prompt": "Watch out! You ___ fall!", "options": ["are going to", "go to", "will going to"], "answer": "are going to", "explanation": "We can see it is about to happen: *are going to*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('2f5b4885-974f-57f9-b06f-79b51780ebef', '50afeb3e-bba3-5898-9e4b-ca6f1609a699', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "gt-check-1", "type": "single_choice", "prompt": "He ___ buy a new laptop.", "options": ["is going to", "are going to", "going"], "answer": "is going to", "explanation": "*He* + *is going to*."}, {"id": "gt-check-2", "type": "single_choice", "prompt": "Which is a question?", "options": ["Are you going to apply?", "You are going to apply.", "You aren''t going to apply."], "answer": "Are you going to apply?", "explanation": "Questions start with *Are / Is*."}, {"id": "gt-check-3", "type": "single_choice", "prompt": "I ___ to the party. I''m too tired.", "options": ["am not going to go", "not going to go", "don''t going to go"], "answer": "am not going to go", "explanation": "Negative: *am not going to* + verb."}, {"id": "gt-check-4", "type": "single_choice", "prompt": "They ___ get married in June.", "options": ["are going to", "is going to", "going to"], "answer": "are going to", "explanation": "*They* + *are going to*."}, {"id": "gt-check-5", "type": "single_choice", "prompt": "What ___ do after university?", "options": ["are you going to", "you are going to", "do you going to"], "answer": "are you going to", "explanation": "Question: *What are you going to do?*"}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('c1cd7d02-01a9-5b6c-af0f-9b8740958cd3', 'will-predictions-offers', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '36c7899a-53b8-54f1-a9b2-bd2e42c04389', 'Will: predictions, offers and quick decisions', 'Use will for the future when you decide now or guess.', 9, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('05cc1c47-9784-5e04-8b1f-dd9aaf2ccd0b', 'c1cd7d02-01a9-5b6c-af0f-9b8740958cd3', 'learn', 1, 'will + verb', '**will** (*''ll*) + base verb is the same for everyone: *I''ll help, she''ll help.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('39aaa7d4-7aca-5105-8c80-3a97110a5b8d', 'c1cd7d02-01a9-5b6c-af0f-9b8740958cd3', 'see', 2, 'Examples', '- *"I''m cold." "I**''ll** close the window."*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('03284e07-a861-5b06-bb44-2fb571d1774c', 'c1cd7d02-01a9-5b6c-af0f-9b8740958cd3', 'try', 3, 'Try it', 'Try it.', '[{"id": "will-try-1", "type": "single_choice", "prompt": "\"I haven''t got any money.\" \"Don''t worry, I ___ pay.\"", "options": ["''ll", "am going to", "pay"], "answer": "''ll", "hint": "Did you decide just now?", "explanation": "A quick decision or offer made now: *I''ll pay*."}, {"id": "will-try-2", "type": "single_choice", "prompt": "Which is correct?", "options": ["She will comes.", "She will come.", "She wills come."], "answer": "She will come.", "explanation": "*will* + base verb, no *-s*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('747d0207-9d2b-54ca-bb27-64d1b9f6b8f3', 'c1cd7d02-01a9-5b6c-af0f-9b8740958cd3', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "will-check-1", "type": "single_choice", "prompt": "I promise I ___ forget.", "options": ["won''t", "don''t", "am not"], "answer": "won''t", "explanation": "A promise: *I won''t forget*."}, {"id": "will-check-2", "type": "single_choice", "prompt": "I think people ___ live on Mars one day.", "options": ["will", "are", "do"], "answer": "will", "explanation": "A prediction: *will live*."}, {"id": "will-check-3", "type": "single_choice", "prompt": "\"This box is heavy.\" \"I ___ help you.\"", "options": ["''ll", "''m helping", "help"], "answer": "''ll", "explanation": "An offer made now: *I''ll help you*."}, {"id": "will-check-4", "type": "single_choice", "prompt": "___ you marry me?", "options": ["Will", "Do", "Are"], "answer": "Will", "explanation": "A request: *Will you ...?*"}, {"id": "will-check-5", "type": "single_choice", "prompt": "Which means \"will not\"?", "options": ["won''t", "willn''t", "don''t"], "answer": "won''t", "explanation": "*won''t* = *will not*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('c3d16d09-bdf0-51f9-b4d7-5ec9a5ebc961', 'future-time-expressions', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '36c7899a-53b8-54f1-a9b2-bd2e42c04389', 'Tomorrow, next week, in two days', 'Say when something will happen.', 10, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('d4e10538-3948-5161-b5ce-b726512c931b', 'c3d16d09-bdf0-51f9-b4d7-5ec9a5ebc961', 'learn', 1, 'When will it happen?', '- **tomorrow** / **tomorrow morning** / **the day after tomorrow**
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('454be7af-3988-5a0f-b6ec-b30b9b4dcc06', 'c3d16d09-bdf0-51f9-b4d7-5ec9a5ebc961', 'see', 2, 'Examples', '- *The shop opens **in** ten minutes.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('f258b48b-6e43-568f-94ec-f88449b09f02', 'c3d16d09-bdf0-51f9-b4d7-5ec9a5ebc961', 'try', 3, 'Try it', 'Try it.', '[{"id": "ftx-try-1", "type": "single_choice", "prompt": "The train leaves ___ five minutes.", "options": ["in", "after", "ago"], "answer": "in", "hint": "ago is for the past.", "explanation": "Future, from now: *in five minutes*."}, {"id": "ftx-try-2", "type": "single_choice", "prompt": "My exam is ___ Monday.", "options": ["next", "the next", "in"], "answer": "next", "explanation": "*next Monday* (no *the*)."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('72d8a604-d42d-5ea6-8f09-5606f5fca28f', 'c3d16d09-bdf0-51f9-b4d7-5ec9a5ebc961', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "ftx-check-1", "type": "single_choice", "prompt": "I''ll finish the report ___.", "options": ["tomorrow", "yesterday", "last week"], "answer": "tomorrow", "explanation": "*tomorrow* is in the future."}, {"id": "ftx-check-2", "type": "single_choice", "prompt": "She''s starting a new job ___ month.", "options": ["next", "last", "ago"], "answer": "next", "explanation": "Future: *next month*."}, {"id": "ftx-check-3", "type": "single_choice", "prompt": "Which is about the future?", "options": ["in three days", "three days ago", "last three days"], "answer": "in three days", "explanation": "*in three days* = three days from now."}, {"id": "ftx-check-4", "type": "single_choice", "prompt": "\"When is the party?\" \"___ Saturday, the day after tomorrow.\"", "options": ["This", "Last", "Ago"], "answer": "This", "explanation": "*This Saturday* = the coming Saturday."}, {"id": "ftx-check-5", "type": "single_choice", "prompt": "I''m busy now. I''ll do it ___.", "options": ["later", "ago", "yesterday"], "answer": "later", "explanation": "*later* = at a time after now."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('e10a9677-e693-5282-a75e-5a944a837556', 'comparatives', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '1af4f4a1-edbe-592f-afce-b0eecf79229a', 'Comparatives: bigger, more expensive', 'Compare two people or things.', 11, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('1992f65d-7169-5ba4-af3c-f4a45b8c6f30', 'e10a9677-e693-5282-a75e-5a944a837556', 'learn', 1, 'Comparing two things', '- Short adjectives: add **-er** + **than**: *tall → tall**er** than*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('99a4c6db-ee80-587e-a216-f651cc8628f8', 'e10a9677-e693-5282-a75e-5a944a837556', 'see', 2, 'Examples', '- *My brother is **taller than** me.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('5c2b3517-acb9-5e64-a73e-fecf5a7c786d', 'e10a9677-e693-5282-a75e-5a944a837556', 'try', 3, 'Try it', 'Try it.', '[{"id": "cmp-try-1", "type": "single_choice", "prompt": "An elephant is ___ than a horse.", "options": ["big", "biger", "bigger"], "answer": "bigger", "hint": "One vowel + one consonant.", "explanation": "*big* doubles the *g*: *bigger*."}, {"id": "cmp-try-2", "type": "single_choice", "prompt": "Gold is ___ than silver.", "options": ["expensiver", "more expensive", "most expensive"], "answer": "more expensive", "explanation": "Long adjective: *more expensive*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('3c489165-1a48-525e-b36f-33e93949e3c4', 'e10a9677-e693-5282-a75e-5a944a837556', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "cmp-check-1", "type": "single_choice", "prompt": "This test is ___ than the last one.", "options": ["easyer", "easier", "more easy"], "answer": "easier", "explanation": "*easy* → *easier* (y → ier)."}, {"id": "cmp-check-2", "type": "single_choice", "prompt": "My cooking is ___ than my sister''s.", "options": ["gooder", "better", "more good"], "answer": "better", "explanation": "*good* → *better* (irregular)."}, {"id": "cmp-check-3", "type": "single_choice", "prompt": "Which is correct?", "options": ["She is older than me.", "She is older that me.", "She is more old than me."], "answer": "She is older than me.", "explanation": "Short adjective + *-er* + *than*."}, {"id": "cmp-check-4", "type": "single_choice", "prompt": "Summer is ___ than winter here.", "options": ["hoter", "hotter", "more hot"], "answer": "hotter", "explanation": "*hot* doubles the *t*: *hotter*."}, {"id": "cmp-check-5", "type": "single_choice", "prompt": "His second song was ___ than his first. Nobody liked it.", "options": ["badder", "worse", "worst"], "answer": "worse", "explanation": "*bad* → *worse*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('2d70b5a3-b81c-5fd6-b8af-8ed2c3c72b00', 'superlatives', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '1af4f4a1-edbe-592f-afce-b0eecf79229a', 'Superlatives: the biggest, the most beautiful', 'Say which is number one in a group.', 12, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('818612e7-bee5-57f2-a199-cf2fd4e04a11', '2d70b5a3-b81c-5fd6-b8af-8ed2c3c72b00', 'learn', 1, 'The top of a group', 'Use a **superlative** to compare one thing with all the others in a group. Use **the**.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('a07d5e01-0a18-5068-bc45-c250cf1570d2', '2d70b5a3-b81c-5fd6-b8af-8ed2c3c72b00', 'see', 2, 'Examples', '- *Mount Everest is **the highest** mountain in the world.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('7e2b5c10-b1c5-5b70-ba50-43a0565c8d9d', '2d70b5a3-b81c-5fd6-b8af-8ed2c3c72b00', 'try', 3, 'Try it', 'Try it.', '[{"id": "sup-try-1", "type": "single_choice", "prompt": "The cheetah is ___ land animal.", "options": ["the fastest", "the faster", "fastest"], "answer": "the fastest", "hint": "Remember ''the''.", "explanation": "Number one in the group: *the fastest*."}, {"id": "sup-try-2", "type": "single_choice", "prompt": "That was ___ day of my life!", "options": ["the most good", "the best", "the better"], "answer": "the best", "explanation": "*good* → *the best*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('5e57bdae-a284-54de-9c6b-3f5613a4915c', '2d70b5a3-b81c-5fd6-b8af-8ed2c3c72b00', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "sup-check-1", "type": "single_choice", "prompt": "She is ___ student in the class.", "options": ["the cleverest", "the more clever", "cleverest than"], "answer": "the cleverest", "explanation": "Superlative with *the*: *the cleverest*."}, {"id": "sup-check-2", "type": "single_choice", "prompt": "This is ___ hotel in town.", "options": ["the most expensive", "the expensivest", "more expensive"], "answer": "the most expensive", "explanation": "Long adjective: *the most expensive*."}, {"id": "sup-check-3", "type": "single_choice", "prompt": "Which is correct?", "options": ["It''s the bigest city.", "It''s the biggest city.", "It''s the most big city."], "answer": "It''s the biggest city.", "explanation": "*big* → *the biggest*."}, {"id": "sup-check-4", "type": "single_choice", "prompt": "Last winter was ___ winter for fifty years.", "options": ["the worst", "the baddest", "the worse"], "answer": "the worst", "explanation": "*bad* → *the worst*."}, {"id": "sup-check-5", "type": "single_choice", "prompt": "Russia is the largest country ___ the world.", "options": ["in", "of", "at"], "answer": "in", "explanation": "*the largest ... in the world*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('ea88e74c-5a62-5149-9ec0-81f635f29d39', 'adverbs-of-manner', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '1af4f4a1-edbe-592f-afce-b0eecf79229a', 'Adverbs: quickly, carefully, well', 'Say how someone does something.', 13, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('68af900b-6016-5952-83b1-ee28723ea988', 'ea88e74c-5a62-5149-9ec0-81f635f29d39', 'learn', 1, 'How?', 'An **adverb of manner** says **how** we do something. Many are adjective + **-ly**: *quick → quick**ly***, *careful → careful**ly***.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('9fef114b-94b0-511a-aaef-ea5a7266995b', 'ea88e74c-5a62-5149-9ec0-81f635f29d39', 'see', 2, 'Examples', '- *Please speak **slowly**.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('538ec4aa-1bd3-5380-8933-c52a22b9c53d', 'ea88e74c-5a62-5149-9ec0-81f635f29d39', 'try', 3, 'Try it', 'Try it.', '[{"id": "adv-try-1", "type": "single_choice", "prompt": "He ran ___ to catch the bus.", "options": ["quick", "quickly", "quicker"], "answer": "quickly", "hint": "Does the word describe the verb?", "explanation": "*ran* is a verb, so we need an adverb: *quickly*."}, {"id": "adv-try-2", "type": "single_choice", "prompt": "She speaks English very ___.", "options": ["good", "well", "goodly"], "answer": "well", "explanation": "The adverb of *good* is *well*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('daf2e5ef-dda6-59fc-9ff0-bfdc43d4e598', 'ea88e74c-5a62-5149-9ec0-81f635f29d39', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "adv-check-1", "type": "single_choice", "prompt": "Read the instructions ___.", "options": ["careful", "carefully", "carefuly"], "answer": "carefully", "explanation": "*careful + ly = carefully*."}, {"id": "adv-check-2", "type": "single_choice", "prompt": "Which word is an adverb?", "options": ["happy", "happily", "happiness"], "answer": "happily", "explanation": "*happily* says how someone does something."}, {"id": "adv-check-3", "type": "single_choice", "prompt": "He is a ___ worker.", "options": ["hard", "hardly", "hardily"], "answer": "hard", "explanation": "Before a noun we need an adjective: *a hard worker*."}, {"id": "adv-check-4", "type": "single_choice", "prompt": "She passed the exam ___.", "options": ["easy", "easily", "easyly"], "answer": "easily", "explanation": "*easy* → *easily*."}, {"id": "adv-check-5", "type": "single_choice", "prompt": "Which is correct?", "options": ["He drives fastly.", "He drives fast.", "He fast drives."], "answer": "He drives fast.", "explanation": "*fast* is the same as an adjective and an adverb."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('c0945ce4-2d17-58cd-b2ef-ca9166927862', 'countable-uncountable', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '1af4f4a1-edbe-592f-afce-b0eecf79229a', 'Countable and uncountable nouns', 'Use a, some and any with nouns you can and can''t count.', 14, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('1bc6631e-6d73-5a52-942c-07feefb2f6eb', 'c0945ce4-2d17-58cd-b2ef-ca9166927862', 'learn', 1, 'Can you count it?', '- **Countable** nouns have a plural: *an apple → apples, a chair → chairs*.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('9d20d642-8748-5c5a-b30d-97c652d1aea5', 'c0945ce4-2d17-58cd-b2ef-ca9166927862', 'see', 2, 'In the kitchen', '*We have **some** eggs and **some** cheese, but we don''t have **any** bread. Is there **any** milk? Can you buy **a loaf of** bread and **a carton of** milk?*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('50885ad9-8173-507a-bb8a-591886ced065', 'c0945ce4-2d17-58cd-b2ef-ca9166927862', 'try', 3, 'Try it', 'Try it.', '[{"id": "cnt-try-1", "type": "single_choice", "prompt": "Can I have ___ water, please?", "options": ["a", "some", "an"], "answer": "some", "hint": "Can you count water?", "explanation": "*water* is uncountable: *some water*, not *a water*."}, {"id": "cnt-try-2", "type": "single_choice", "prompt": "Which noun is uncountable?", "options": ["chair", "information", "pen"], "answer": "information", "explanation": "*information* has no plural."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('f53064c3-5d8b-5960-9cec-afd80edb38d1', 'c0945ce4-2d17-58cd-b2ef-ca9166927862', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "cnt-check-1", "type": "single_choice", "prompt": "There isn''t ___ sugar in my tea.", "options": ["some", "any", "a"], "answer": "any", "explanation": "Negative sentence: *any*."}, {"id": "cnt-check-2", "type": "single_choice", "prompt": "Which is correct?", "options": ["She gave me some advices.", "She gave me some advice.", "She gave me an advice."], "answer": "She gave me some advice.", "explanation": "*advice* is uncountable: no *-s*, no *an*."}, {"id": "cnt-check-3", "type": "single_choice", "prompt": "I bought ___ oranges at the market.", "options": ["some", "any", "an"], "answer": "some", "explanation": "Positive sentence with a plural: *some*."}, {"id": "cnt-check-4", "type": "single_choice", "prompt": "Are there ___ questions?", "options": ["some", "any", "a"], "answer": "any", "explanation": "Question: *any*."}, {"id": "cnt-check-5", "type": "single_choice", "prompt": "I''d like ___ of bread, please.", "options": ["a slice", "a bread", "breads"], "answer": "a slice", "explanation": "Count bread with *a slice of* or *a loaf of*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('920394b6-247b-55bc-9855-0913e628db81', 'much-many-a-lot', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '1af4f4a1-edbe-592f-afce-b0eecf79229a', 'How much, how many, a lot of', 'Talk about quantity.', 15, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('9e4e2d97-299c-578f-b1ba-7174780dc216', '920394b6-247b-55bc-9855-0913e628db81', 'learn', 1, 'much / many / a lot of', '- **many** + plural countable: *many books*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('16852e18-53a1-530b-921e-7b59d63b65fa', '920394b6-247b-55bc-9855-0913e628db81', 'see', 2, 'Examples', '- ***How many** students are in your class?* — *About twenty.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('04d06450-3576-52c3-88b7-2966c8e7d022', '920394b6-247b-55bc-9855-0913e628db81', 'try', 3, 'Try it', 'Try it.', '[{"id": "mm-try-1", "type": "single_choice", "prompt": "How ___ eggs do we need?", "options": ["much", "many", "lot"], "answer": "many", "hint": "Can you count eggs?", "explanation": "*eggs* are countable: *how many*."}, {"id": "mm-try-2", "type": "single_choice", "prompt": "I don''t drink ___ coffee.", "options": ["many", "much", "a lots"], "answer": "much", "explanation": "*coffee* is uncountable: *much*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('2ecb9f6a-7907-56f4-b9ab-69ebce466331', '920394b6-247b-55bc-9855-0913e628db81', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "mm-check-1", "type": "single_choice", "prompt": "How ___ is the ticket?", "options": ["many", "much", "lot"], "answer": "much", "explanation": "Asking about price/money: *How much*."}, {"id": "mm-check-2", "type": "single_choice", "prompt": "There are ___ trees in this park.", "options": ["a lot of", "much", "a lot"], "answer": "a lot of", "explanation": "*a lot of* + plural noun."}, {"id": "mm-check-3", "type": "single_choice", "prompt": "We haven''t got ___ time.", "options": ["many", "much", "a lots of"], "answer": "much", "explanation": "*time* is uncountable: *much*."}, {"id": "mm-check-4", "type": "single_choice", "prompt": "How ___ languages do you speak?", "options": ["much", "many", "lot of"], "answer": "many", "explanation": "*languages* are countable: *how many*."}, {"id": "mm-check-5", "type": "single_choice", "prompt": "Which is correct?", "options": ["She has a lot of friends.", "She has much friends.", "She has a lot friends."], "answer": "She has a lot of friends.", "explanation": "*a lot of* + plural: *a lot of friends*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('3acf8c0c-98a1-5d91-88b8-bfe212298852', 'object-pronouns', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '89ce1393-96f5-54c6-81dd-63ccbbe8f704', 'Object pronouns: me, him, them', 'Use the right pronoun after a verb or a preposition.', 16, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('cda4ae72-5af7-59e5-b24e-b91b37a7364c', '3acf8c0c-98a1-5d91-88b8-bfe212298852', 'learn', 1, 'Subject and object', 'A **subject** pronoun does the action. An **object** pronoun comes **after** a verb or a preposition.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('57fd71b0-c1ef-55a3-b693-c0575e0b9a0c', '3acf8c0c-98a1-5d91-88b8-bfe212298852', 'see', 2, 'Examples', '- *I like **her**.* (not *I like she*)
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('8106ca2a-fe9c-5b44-aaa6-bd83356d45c8', '3acf8c0c-98a1-5d91-88b8-bfe212298852', 'try', 3, 'Try it', 'Try it.', '[{"id": "obj-try-1", "type": "single_choice", "prompt": "Tom is my friend. I see ___ every day.", "options": ["he", "him", "his"], "answer": "him", "hint": "It comes after the verb.", "explanation": "After the verb *see*: object *him*."}, {"id": "obj-try-2", "type": "single_choice", "prompt": "Please wait for ___.", "options": ["we", "us", "our"], "answer": "us", "explanation": "After the preposition *for*: *us*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('e320e0c4-6a2b-5190-830c-151d2180ebda', '3acf8c0c-98a1-5d91-88b8-bfe212298852', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "obj-check-1", "type": "single_choice", "prompt": "My parents live far away. I miss ___.", "options": ["they", "them", "their"], "answer": "them", "explanation": "Object of *miss*: *them*."}, {"id": "obj-check-2", "type": "single_choice", "prompt": "Can you give ___ the salt, please?", "options": ["I", "me", "my"], "answer": "me", "explanation": "Object: *me*."}, {"id": "obj-check-3", "type": "single_choice", "prompt": "Anna sent ___ a message. He replied quickly.", "options": ["him", "he", "his"], "answer": "him", "explanation": "Object of *sent*: *him*."}, {"id": "obj-check-4", "type": "single_choice", "prompt": "Which is correct?", "options": ["She called me last night.", "She called I last night.", "Her called me last night."], "answer": "She called me last night.", "explanation": "Subject *she*, object *me*."}, {"id": "obj-check-5", "type": "single_choice", "prompt": "This is my new phone. Do you like ___?", "options": ["it", "its", "them"], "answer": "it", "explanation": "One thing: *it*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('93cb0bb7-cbcb-51c0-87b3-27d91dfeff01', 'must-have-to', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '89ce1393-96f5-54c6-81dd-63ccbbe8f704', 'Must and have to', 'Talk about rules and things that are necessary.', 17, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('6dbc4b86-3e11-5f6a-b608-c00160aecfb3', '93cb0bb7-cbcb-51c0-87b3-27d91dfeff01', 'learn', 1, 'Rules and needs', '- **must** + verb: a strong rule, or the speaker feels it is necessary: *I **must** call my mum.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('6feadf09-7980-5f3a-8a2c-bc0d2796d588', '93cb0bb7-cbcb-51c0-87b3-27d91dfeff01', 'see', 2, 'Examples', '- *Students **must** switch off their phones in the exam room.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('83edf8d3-b6cb-5bc2-be2e-7186b54c49d2', '93cb0bb7-cbcb-51c0-87b3-27d91dfeff01', 'try', 3, 'Try it', 'Try it.', '[{"id": "must-try-1", "type": "single_choice", "prompt": "My sister ___ work on Saturdays.", "options": ["have to", "has to", "must to"], "answer": "has to", "hint": "Third person singular.", "explanation": "*she* → *has to*."}, {"id": "must-try-2", "type": "single_choice", "prompt": "It''s free. You ___ pay.", "options": ["mustn''t", "don''t have to", "must"], "answer": "don''t have to", "explanation": "Not necessary: *don''t have to*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('d8c6036e-ae88-548d-9b60-9c271c0a6b46', '93cb0bb7-cbcb-51c0-87b3-27d91dfeff01', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "must-check-1", "type": "single_choice", "prompt": "You ___ cross the road when the light is red. It''s dangerous.", "options": ["mustn''t", "don''t have to", "has to"], "answer": "mustn''t", "explanation": "Not allowed: *mustn''t*."}, {"id": "must-check-2", "type": "single_choice", "prompt": "Yesterday I ___ stay late at work.", "options": ["must", "had to", "have to"], "answer": "had to", "explanation": "Past of *have to*: *had to*."}, {"id": "must-check-3", "type": "single_choice", "prompt": "Which is correct?", "options": ["I must go now.", "I must to go now.", "I musts go now."], "answer": "I must go now.", "explanation": "*must* + verb without *to*."}, {"id": "must-check-4", "type": "single_choice", "prompt": "The museum is free on Mondays, so you ___ buy a ticket.", "options": ["mustn''t", "don''t have to", "must"], "answer": "don''t have to", "explanation": "You can choose: *don''t have to*."}, {"id": "must-check-5", "type": "single_choice", "prompt": "Do you ___ wear a tie at work?", "options": ["have to", "must to", "has to"], "answer": "have to", "explanation": "Question: *Do you have to ...?*"}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('03abd5cf-ee98-5072-9724-b42426da3206', 'should-advice', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '89ce1393-96f5-54c6-81dd-63ccbbe8f704', 'Should for advice', 'Give and ask for advice.', 18, 10, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('207e4b88-94a3-5ffa-9134-6a1faed86b2f', '03abd5cf-ee98-5072-9724-b42426da3206', 'learn', 1, 'Giving advice', 'Use **should** + verb to say something is a good idea. Use **shouldn''t** for a bad idea.
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('9ae0c52b-a4d3-568e-8e99-9bd6a96b18c2', '03abd5cf-ee98-5072-9724-b42426da3206', 'see', 2, 'Examples', '- *You look tired. You **should** go to bed early.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('90955300-ab3d-5584-af6e-f2b5f9a07f72', '03abd5cf-ee98-5072-9724-b42426da3206', 'try', 3, 'Try it', 'Try it.', '[{"id": "sh-try-1", "type": "single_choice", "prompt": "You have a cold. You ___ drink hot tea.", "options": ["should", "shouldn''t", "should to"], "answer": "should", "hint": "Is it a good idea?", "explanation": "A good idea: *should*."}, {"id": "sh-try-2", "type": "single_choice", "prompt": "He ___ drive so fast. It''s dangerous.", "options": ["should", "shouldn''t", "shoulds"], "answer": "shouldn''t", "explanation": "A bad idea: *shouldn''t*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('4919bbcb-eb23-5966-bd86-4d6ce549abb7', '03abd5cf-ee98-5072-9724-b42426da3206', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "sh-check-1", "type": "single_choice", "prompt": "Which is correct?", "options": ["She should study more.", "She shoulds study more.", "She should to study more."], "answer": "She should study more.", "explanation": "*should* + verb, no *-s*, no *to*."}, {"id": "sh-check-2", "type": "single_choice", "prompt": "___ I call her now or later?", "options": ["Should", "Do should", "Am should"], "answer": "Should", "explanation": "Question: *Should I ...?*"}, {"id": "sh-check-3", "type": "single_choice", "prompt": "You ___ stay up late before an exam.", "options": ["should", "shouldn''t", "must to"], "answer": "shouldn''t", "explanation": "A bad idea: *shouldn''t*."}, {"id": "sh-check-4", "type": "single_choice", "prompt": "It''s cold outside. You ___ take a coat.", "options": ["should", "shouldn''t", "should not to"], "answer": "should", "explanation": "Good advice: *should*."}, {"id": "sh-check-5", "type": "single_choice", "prompt": "What ___ I do? I lost my keys.", "options": ["should", "shoulds", "do should"], "answer": "should", "explanation": "*What should I do?*"}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('868ea080-c5d5-5204-9c9f-41a982c4b5b5', 'linking-words', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '89ce1393-96f5-54c6-81dd-63ccbbe8f704', 'Linking words: and, but, because, so', 'Join two ideas in one sentence.', 19, 12, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('7ebdf723-2e2d-5c6f-bf1f-e8e32e0dc1e9', '868ea080-c5d5-5204-9c9f-41a982c4b5b5', 'learn', 1, 'Joining ideas', '- **and** adds an idea: *I like tea **and** coffee.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('443cc078-3d6c-5ce6-b0c7-80831d7183df', '868ea080-c5d5-5204-9c9f-41a982c4b5b5', 'see', 2, 'Examples', '- *She plays the piano **and** sings.*
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('b106c93b-78dd-51b5-a608-0366d4dad8c2', '868ea080-c5d5-5204-9c9f-41a982c4b5b5', 'try', 3, 'Try it', 'Try it.', '[{"id": "lk-try-1", "type": "single_choice", "prompt": "I was hungry, ___ I made a sandwich.", "options": ["because", "so", "but"], "answer": "so", "hint": "What happened next?", "explanation": "Result: *so*."}, {"id": "lk-try-2", "type": "single_choice", "prompt": "The phone is cheap ___ good.", "options": ["but", "because", "so"], "answer": "but", "explanation": "Cheap vs. good is a surprise: *but*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('672464c3-cdca-5609-a75c-10bd5e85be68', '868ea080-c5d5-5204-9c9f-41a982c4b5b5', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "lk-check-1", "type": "single_choice", "prompt": "He missed the bus ___ he woke up late.", "options": ["so", "because", "and"], "answer": "because", "explanation": "Reason: *because*."}, {"id": "lk-check-2", "type": "single_choice", "prompt": "I bought bread ___ milk.", "options": ["and", "but", "so"], "answer": "and", "explanation": "Adding: *and*."}, {"id": "lk-check-3", "type": "single_choice", "prompt": "The film was long, ___ it was very good.", "options": ["because", "so", "but"], "answer": "but", "explanation": "Contrast: *but*."}, {"id": "lk-check-4", "type": "single_choice", "prompt": "It was late, ___ we went home.", "options": ["so", "because", "but"], "answer": "so", "explanation": "Result: *so*."}, {"id": "lk-check-5", "type": "single_choice", "prompt": "She is happy ___ she passed her test.", "options": ["so", "because", "but"], "answer": "because", "explanation": "Reason: *because*."}]'::jsonb);
insert into public.lessons (id, slug, learning_level_id, unit_id, title, summary, sort_order, estimated_minutes, status) values ('9cb9174d-7854-5fe6-b9cf-9fea6e058956', 'sequence-words', 'd17b31cb-2ed4-5377-b203-17024625bd0e', '89ce1393-96f5-54c6-81dd-63ccbbe8f704', 'Writing a short story: first, then, after that', 'Put events in order in a short paragraph.', 20, 14, 'published');
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('6752bdea-bbea-5d80-95a9-d58e36e492f0', '9cb9174d-7854-5fe6-b9cf-9fea6e058956', 'learn', 1, 'Telling events in order', 'Use **sequence words** to show the order of events:
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('27e8c4f2-f120-5e27-afd1-bcdb34d6ded9', '9cb9174d-7854-5fe6-b9cf-9fea6e058956', 'see', 2, 'Example paragraph', '*Last Saturday was a busy day. **First,** I cleaned my flat. **Then** I went to the market and bought some fruit. **After that,** I met my friend for lunch. **Finally,** we watched a film in the evening.*', '[]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('93c24b56-765c-5f6f-9eca-55518ffdf5b4', '9cb9174d-7854-5fe6-b9cf-9fea6e058956', 'try', 3, 'Try it', 'Try it.', '[{"id": "sq-try-1", "type": "single_choice", "prompt": "Which word starts the story?", "options": ["Finally", "First", "After that"], "answer": "First", "hint": "Which comes at the beginning?", "explanation": "*First* is for the first event."}, {"id": "sq-try-2", "type": "single_choice", "prompt": "___, I went to bed. It was the end of a long day.", "options": ["First", "Finally", "Then"], "answer": "Finally", "explanation": "The last event: *Finally*."}]'::jsonb);
insert into public.lesson_sections (id, lesson_id, kind, sort_order, title, body_md, exercises) values ('bce50f73-20e7-5b77-8072-d7d3b551ea6a', '9cb9174d-7854-5fe6-b9cf-9fea6e058956', 'check', 4, 'Check', 'Answer the questions.', '[{"id": "sq-check-1", "type": "single_choice", "prompt": "Choose the best order: (a) I had breakfast. (b) I woke up. (c) I went to work.", "options": ["b, a, c", "a, b, c", "c, b, a"], "answer": "b, a, c", "explanation": "Wake up → breakfast → work."}, {"id": "sq-check-2", "type": "single_choice", "prompt": "Which sentence is punctuated correctly?", "options": ["After that, we went home.", "After that we, went home.", "After, that we went home."], "answer": "After that, we went home.", "explanation": "Comma after *After that*."}, {"id": "sq-check-3", "type": "single_choice", "prompt": "Yesterday I ___ to the park first.", "options": ["go", "went", "goes"], "answer": "went", "explanation": "A story about yesterday: past simple *went*."}, {"id": "sq-check-4", "type": "single_choice", "prompt": "Which word can replace *Then*?", "options": ["Next", "Finally", "First"], "answer": "Next", "explanation": "*Next* and *Then* both mean the following step."}, {"id": "sq-check-5", "type": "single_choice", "prompt": "Which is the best last sentence of a story?", "options": ["Finally, I fell asleep.", "First, I fell asleep.", "Then first I fell asleep."], "answer": "Finally, I fell asleep.", "explanation": "*Finally* introduces the last event."}]'::jsonb);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('980cfa9c-04d2-5213-b25b-9c2ffdd77f6d', 'sst-0001', 'f7f6fdbd-4e43-52be-9694-1e49b80c2f7e', 'intermediate', 'Listen to the talk. Then write a short summary of its main points in your own words.', '{"audio_script": "Many people throw away food that is still safe to eat because they misunderstand date labels. A ''best before'' date is about quality, not safety, so food is often fine after that date. A ''use by'' date, however, is about safety and should be followed. Clearer labels and simple public information could reduce household food waste significantly."}'::jsonb, '{"model_answer": "The speaker explained that much food waste happens because people confuse date labels. ''Best before'' refers to quality, so food can often be eaten after this date, while ''use by'' is a safety limit that must be respected. The speaker suggested that clearer labelling and better public information could greatly reduce the amount of food households throw away."}'::jsonb, 'Include the problem, the difference between the two labels and the suggested solution.', 'Summarize a short talk in a few clear sentences.', array['Content', 'Form', 'Grammar', 'Vocabulary', 'Spelling']::text[], array['food wasted due to label confusion', 'best before = quality', 'use by = safety', 'clearer labels reduce waste']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0c544db4-2d46-5fe2-908f-3e81429ae100', 'sst-0002', 'f7f6fdbd-4e43-52be-9694-1e49b80c2f7e', 'advanced', 'Listen to the talk. Then write a short summary of its main points in your own words.', '{"audio_script": "Green roofs, which are roofs covered with plants, are becoming popular in large cities. They absorb rainwater, which reduces flooding, and they keep buildings cooler in summer. They also provide habitats for insects. The main barriers are the cost of installation and the need to check that older buildings can support the extra weight."}'::jsonb, '{"model_answer": "The talk described green roofs, which are planted roofs increasingly used in cities. They help by absorbing rain to reduce flooding, cooling buildings in hot weather and supporting insect life. However, they can be expensive to install, and older buildings must be checked to make sure they are strong enough to carry the added weight of soil and plants."}'::jsonb, 'Give the definition, the benefits and the barriers.', 'Summarize benefits and limitations from a talk.', array['Content', 'Form', 'Grammar', 'Vocabulary', 'Spelling']::text[], array['green roofs = planted roofs', 'reduce flooding, cool buildings, insect habitat', 'cost and weight barriers']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'lmcm-0001', '98cdddc4-46fd-53a3-aa5d-862c3528a2fe', 'intermediate', 'Listen, then choose every answer that matches what the speaker says. There is more than one.', '{"audio_script": "Our study group found that reading aloud helped us remember new words, and testing each other every Friday showed us which topics we still did not understand. Highlighting the textbook, though, did not seem to make much difference.", "question": "Which study methods did the speaker find useful?"}'::jsonb, '{"correct": ["A", "B"]}'::jsonb, 'Reading aloud and Friday tests helped. Highlighting "did not seem to make much difference". Videos were not mentioned.', 'Track which ideas the speaker supports or rejects.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e383fddb-d9a1-50cc-922e-69815c81aeff', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'A', 'Reading aloud', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('849358b2-f150-5d4b-938c-36dca8e41f18', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'B', 'Weekly testing of each other', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('faa186f5-61bb-5aa2-813d-db0050ce7ae1', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'C', 'Highlighting the textbook', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('9ef36130-6d84-5666-b9e0-12d3b11b96ea', 'eb1d6cdc-36fe-51eb-bc94-0d3b0776580e', 'D', 'Watching videos', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'lmcm-0002', '98cdddc4-46fd-53a3-aa5d-862c3528a2fe', 'advanced', 'Listen, then choose every answer that matches what the speaker says. There is more than one.', '{"audio_script": "When the city introduced free buses for students, two things happened. Car traffic near schools fell, and attendance in the poorer districts rose. Bus crowding at peak times, however, became a new challenge.", "question": "What results of the free bus scheme are mentioned?"}'::jsonb, '{"correct": ["A", "B", "C"]}'::jsonb, 'The speaker mentions all three results A, B and C. Adult prices are not mentioned.', 'Catch positive and negative outcomes.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('36be7cca-f457-5a80-b6ec-f7c2df047a85', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'A', 'Less car traffic near schools', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('08cd8d4e-956b-5a98-a3c7-e9f5449fefcf', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'B', 'Higher attendance in poorer areas', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('34f78a61-ec35-520d-b8d7-a0b2ebfb91ed', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'C', 'Crowded buses at busy times', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('8053e63f-9cc1-5faf-b198-bfd78711eda1', '2ff5f89e-b291-5319-8839-1c61c2d8b5d9', 'D', 'Lower bus ticket prices for adults', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('16df8aef-d6bb-5188-89fa-724882ff4eec', 'lfib-0001', 'f0bf404a-0ff4-565e-a293-9130eb80ecd8', 'beginner', 'Listen and type the word you hear in each gap.', '{"audio_script": "Please bring your student card and a pencil to the exam room.", "text": "Please bring your student {{1}} and a {{2}} to the exam room."}'::jsonb, '{"blanks": {"1": "card", "2": "pencil"}}'::jsonb, 'Listen for the exact words and check the spelling.', 'Write exact words heard in a sentence.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1dcee511-c566-50c1-9725-4cceae95b9f4', 'lfib-0002', 'f0bf404a-0ff4-565e-a293-9130eb80ecd8', 'intermediate', 'Listen and type the word you hear in each gap.', '{"audio_script": "The research team collected data from schools in three different regions over a period of two years.", "text": "The research team collected {{1}} from schools in three different {{2}} over a period of two years."}'::jsonb, '{"blanks": {"1": "data", "2": "regions"}}'::jsonb, '"regions" is plural because of "three different".', 'Use grammar clues to check what you heard.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('6dc2c902-8ede-5643-bc6b-a657deab0b95', 'hcs-0001', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'intermediate', 'Listen, then choose the summary that matches the talk best.', '{"audio_script": "Many young people now choose to rent rather than buy homes. Rising house prices are one reason, but surveys show that some also value the freedom to move for work."}'::jsonb, '{"correct": ["B"]}'::jsonb, 'B includes both reasons: prices and freedom to move.', 'Choose the summary that includes all main points.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('4f8fdeca-4f7e-51a0-b7cb-fd5893297eef', '6dc2c902-8ede-5643-bc6b-a657deab0b95', 'A', 'Young people rent mainly because they dislike owning property.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3344c555-84f5-537a-93f0-0ef350676091', '6dc2c902-8ede-5643-bc6b-a657deab0b95', 'B', 'Young people increasingly rent because of high prices and a wish for flexibility.', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('404b1098-85b8-5b49-978e-83b6b58d8634', '6dc2c902-8ede-5643-bc6b-a657deab0b95', 'C', 'House prices are falling, so fewer young people buy homes.', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1489e580-3946-5fbf-bb18-d062e7bbf653', 'hcs-0002', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'advanced', 'Listen, then choose the summary that matches the talk best.', '{"audio_script": "Electric cars produce no exhaust while driving, but their batteries require mining for materials such as lithium. Their overall environmental benefit depends largely on how the electricity used to charge them is produced."}'::jsonb, '{"correct": ["C"]}'::jsonb, 'C keeps the balanced view of the speaker. A and B are too extreme.', 'Avoid summaries that are too extreme.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('09e780cd-d1ad-5f78-b3be-9448e253bc9c', '1489e580-3946-5fbf-bb18-d062e7bbf653', 'A', 'Electric cars are always better for the environment than petrol cars.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e3bf8d8f-dc23-53e7-a961-c34697d49adb', '1489e580-3946-5fbf-bb18-d062e7bbf653', 'B', 'Battery mining makes electric cars worse than petrol cars.', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('cc8ed646-b6ad-5e3c-a0a8-45036b9809b8', '1489e580-3946-5fbf-bb18-d062e7bbf653', 'C', 'Electric cars have no exhaust, but their real benefit depends on battery materials and electricity sources.', true, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'lmcs-0001', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'beginner', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "The college gym will be closed next Monday for cleaning. It will open again on Tuesday at seven in the morning.", "question": "When will the gym open again?"}'::jsonb, '{"correct": ["B"]}'::jsonb, '"open again on Tuesday at seven in the morning".', 'Catch days and times.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('47a98f35-4cc3-5d6e-a23a-d7b7ed08b08b', '357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'A', 'Monday at 7 am', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('cefa0a46-e533-511a-b7aa-80666089ff6d', '357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'B', 'Tuesday at 7 am', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('2e529c7c-108d-508d-a70c-f3ebb92f3b89', '357d52ca-a543-5c79-9aa1-1f0d96333cdb', 'C', 'Tuesday at 7 pm', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'lmcs-0002', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'intermediate', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "I used to think that multitasking saved time. But after tracking my work for a month, I realised I finished tasks faster when I focused on one thing at a time.", "question": "What is the speaker''s conclusion?"}'::jsonb, '{"correct": ["B"]}'::jsonb, '"used to think" shows an old belief. The conclusion is that single-tasking was faster.', 'Recognise a change of opinion.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('a0f6c074-d3a6-5c8d-9a40-fec347d7c676', '0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'A', 'Multitasking saves time.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('ca60814c-1c53-5439-9821-936007c7bb8a', '0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'B', 'Focusing on one task is more efficient.', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e3c397b6-8ee5-51de-a525-e9a6feb148c8', '0a3a4871-e64f-566d-86bb-fa6d69e72f45', 'C', 'Tracking work wastes time.', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a7e49192-cb17-599e-8c85-8776356d85fa', 'smw-0001', 'fd9c8418-e1bd-5d16-b156-36ed58e7f9ea', 'beginner', 'Listen. A beep replaces the last word or words. Choose what the speaker most likely said.', '{"audio_script": "It was raining heavily all morning, so we decided to stay [BEEP]."}'::jsonb, '{"correct": ["A"]}'::jsonb, 'Heavy rain is a reason to stay inside.', 'Predict an ending from cause and effect.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('dd644ddf-f8c2-5f38-86fe-5672e6353305', 'a7e49192-cb17-599e-8c85-8776356d85fa', 'A', 'inside', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('ebeecc19-5922-5df5-8b0a-7e5194d1cfab', 'a7e49192-cb17-599e-8c85-8776356d85fa', 'B', 'outside', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('35e23022-9d25-5734-802d-550e9a2a496b', 'a7e49192-cb17-599e-8c85-8776356d85fa', 'C', 'awake', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('e6d1dc08-abb6-5b37-abec-5fb759c01873', 'smw-0002', 'fd9c8418-e1bd-5d16-b156-36ed58e7f9ea', 'intermediate', 'Listen. A beep replaces the last word or words. Choose what the speaker most likely said.', '{"audio_script": "The first experiment failed, and so did the second. However, the team did not give up, and the third attempt was finally a [BEEP]."}'::jsonb, '{"correct": ["B"]}'::jsonb, '"However" and "finally" show a positive change: success.', 'Use contrast words to predict meaning.', array['Listening']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('83d3dae6-366e-5e18-b941-620418b8ec87', 'e6d1dc08-abb6-5b37-abec-5fb759c01873', 'A', 'disaster', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('66bdd551-1c5c-519b-bf28-8d268027a15d', 'e6d1dc08-abb6-5b37-abec-5fb759c01873', 'B', 'success', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('da093a23-f964-5869-beb1-787b2a6539e5', 'e6d1dc08-abb6-5b37-abec-5fb759c01873', 'C', 'mistake', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('4be9ac65-7a89-5548-bc5d-534c47e036f0', 'hiw-0001', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'beginner', 'Read the text while you listen. Click each word that is different from what the speaker says.', '{"audio_script": "Our class visited the science museum on Thursday and saw a large model of the planets.", "transcript": "Our class visited the history museum on Thursday and saw a small model of the planets."}'::jsonb, '{"incorrect_words": [{"index": 4, "word": "history", "spoken": "science"}, {"index": 11, "word": "small", "spoken": "large"}]}'::jsonb, 'The speaker said "science" and "large".', 'Follow a transcript while listening.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('53c94e83-dfa7-538a-bff2-1960096b9d04', 'hiw-0002', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'intermediate', 'Read the text while you listen. Click each word that is different from what the speaker says.', '{"audio_script": "The survey found that most employees preferred flexible hours to a higher salary.", "transcript": "The survey showed that most employees preferred flexible days to a higher salary."}'::jsonb, '{"incorrect_words": [{"index": 2, "word": "showed", "spoken": "found"}, {"index": 8, "word": "days", "spoken": "hours"}]}'::jsonb, 'The speaker said "found" and "hours".', 'Notice small changes in meaning.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3bc936f4-8162-5200-bb45-24a66e81027e', 'wfd-0001', 'c4f6e94e-f068-5719-b756-005c6e22e8fa', 'beginner', 'Listen to the sentence. Type it exactly as you hear it.', '{"audio_script": "The lecture will start in the main hall."}'::jsonb, '{"reference_text": "The lecture will start in the main hall."}'::jsonb, 'Write every word, and check small words like "the" and "in".', 'Write a short sentence accurately.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d6c45e86-1888-5bad-a845-e3fd87b13f8a', 'wfd-0002', 'c4f6e94e-f068-5719-b756-005c6e22e8fa', 'intermediate', 'Listen to the sentence. Type it exactly as you hear it.', '{"audio_script": "Applications must be submitted before the end of the month."}'::jsonb, '{"reference_text": "Applications must be submitted before the end of the month."}'::jsonb, 'Check the plural "Applications" and the passive "be submitted".', 'Write a sentence with a passive verb.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('30c5e482-7ecb-5a77-a237-bb23a3b00e84', 'rwfib-0001', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "Regular exercise is good for both the body and the {{1}}. People who walk every day often {{2}} better at night.", "blanks": {"1": ["mind", "minds", "mindful"], "2": ["sleep", "sleeping", "slept"]}}'::jsonb, '{"blanks": {"1": "mind", "2": "sleep"}}'::jsonb, '"the body and the mind" needs a singular noun. After "often" in the present simple, we use the base verb "sleep".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('07320d69-3094-5621-8c41-6c8e0e14c1ae', 'rwfib-0002', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "The museum''s new exhibition has {{1}} large crowds since it opened. Visitors are especially {{2}} in the section on ancient maps.", "blanks": {"1": ["attracted", "attractive", "attraction"], "2": ["interested", "interesting", "interest"]}}'::jsonb, '{"blanks": {"1": "attracted", "2": "interested"}}'::jsonb, '"has ... since" needs a past participle: "attracted". People feel "interested"; things are "interesting".', 'Use word forms (verb, adjective, noun) correctly.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d2005a3b-a801-50a6-87d0-42f6f3a800aa', 'rmcm-0001', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Coral reefs cover a very small part of the ocean floor, yet they are home to about a quarter of all known marine species. Reefs also protect coastlines by breaking up strong waves. Rising sea temperatures cause corals to lose the algae that feed them, a process known as bleaching.", "question": "According to the text, which of the following are true about coral reefs?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'A matches "a quarter of all known marine species". C matches "breaking up strong waves". The text says reefs cover a small part of the floor and bleaching comes from rising temperatures.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('07a4514c-e738-57e0-b520-03862848b8b1', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'A', 'They support a large share of marine species.', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('34c5a5e9-f21b-5641-9a3c-3c2a5ff6ff3c', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'B', 'They cover most of the ocean floor.', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('f84eb6cb-4f9a-511c-acd9-ba833f34afdd', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'C', 'They reduce the force of waves on coasts.', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3ae83b9c-87cf-58fd-90b5-771ee1476d7e', 'd2005a3b-a801-50a6-87d0-42f6f3a800aa', 'D', 'Bleaching is caused by cold water.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('4dea0915-a43e-5f82-84bf-eddc720794dd', 'rmcm-0002', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Night shifts can disturb the body''s internal clock. Workers on long-term night schedules report more digestive problems and poorer sleep quality. Some employers now offer brighter lighting during shifts and blackout blinds for daytime rest, which appear to reduce these effects.", "question": "Which measures does the writer mention to reduce the effects of night work?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'Only lighting and blackout blinds are mentioned as measures.', 'Separate stated measures from ideas that are not in the text.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('64ff5409-b34f-52f9-a230-d80f53401329', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'A', 'Brighter lighting at work', true, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('dcb833ac-3f70-5d78-9873-bd6aa4f418fb', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'B', 'Shorter shifts', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('554b4178-8ec8-5898-9bad-148b21a8c598', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'C', 'Blackout blinds for sleeping in the day', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('6f6c1281-06d9-5881-85d0-f0698687819f', '4dea0915-a43e-5f82-84bf-eddc720794dd', 'D', 'Special diets', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('732d1e83-ee96-5d63-91d4-8dc05f702b61', 'rop-0001', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "First, fill the kettle with fresh water and switch it on."}, {"id": "p2", "text": "Finally, add milk or sugar if you like, and enjoy your tea."}, {"id": "p3", "text": "While the water heats, put a tea bag into a cup."}, {"id": "p4", "text": "When the water boils, pour it over the tea bag and wait three minutes."}]}'::jsonb, '{"order": ["p1", "p3", "p4", "p2"]}'::jsonb, 'Follow the time words: First, While, When, Finally.', 'Use sequence words to order a process.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('156adfac-8b84-5daa-93c7-77a394bcbd53', 'rop-0002', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "As a result, the town decided to build a new cycle lane along the river."}, {"id": "p2", "text": "Traffic in the town centre had become a serious problem by 2020."}, {"id": "p3", "text": "A survey showed that many residents would cycle if they felt safer on the roads."}, {"id": "p4", "text": "Since the lane opened, the number of cyclists has doubled."}]}'::jsonb, '{"order": ["p2", "p3", "p1", "p4"]}'::jsonb, 'Problem, then evidence, then decision ("As a result"), then outcome ("Since").', 'Order a problem-solution text using linking words.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('bc8af956-5a7d-5536-a64c-efd187515308', 'rfib-0001', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Water {{1}} at 100 degrees Celsius at sea level. When it gets very cold, it {{2}} into ice.", "word_bank": ["boils", "turns", "grows", "melts"]}'::jsonb, '{"blanks": {"1": "boils", "2": "turns"}}'::jsonb, 'Water boils at 100°C. It "turns into" ice when it freezes. "melts" is the opposite process.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3b497e9b-061a-5c01-b8ff-d590b89af68c', 'rfib-0002', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The company plans to {{1}} its office in March. Staff will be able to work from home during the {{2}} period.", "word_bank": ["renovate", "transition", "decorate", "pause"]}'::jsonb, '{"blanks": {"1": "renovate", "2": "transition"}}'::jsonb, '"renovate its office" is a natural collocation. "transition period" is a fixed phrase.', 'Recognise common academic collocations.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('46fcce68-9c69-55e3-ad8b-592732463f73', 'rmcs-0001', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "The town market opens every Saturday from 8 am to 1 pm. Most stalls sell fresh fruit and vegetables, but there are also stalls selling bread and handmade soap.", "question": "What is the main thing sold at the market?"}'::jsonb, '{"correct": ["B"]}'::jsonb, '"Most stalls" sell fruit and vegetables. Bread and soap are "also" sold, so they are not the main thing.', 'Identify the main idea versus extra details.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('4923ff12-c273-5627-9b82-38e02139f81f', '46fcce68-9c69-55e3-ad8b-592732463f73', 'A', 'Bread', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e1b77dde-e4a2-5d6f-8be2-9adcc066263f', '46fcce68-9c69-55e3-ad8b-592732463f73', 'B', 'Fresh fruit and vegetables', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('b6e4dd89-8f36-5758-9b45-75bf5649c087', '46fcce68-9c69-55e3-ad8b-592732463f73', 'C', 'Handmade soap', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9418db97-0971-52f4-9984-f14a8d308ca3', 'rmcs-0002', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "While online courses offer flexibility, completion rates remain low. Studies suggest that learners who set a fixed weekly study time and join a discussion group are much more likely to finish.", "question": "What is the writer''s main point?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'The text says completion is low, but fixed times and groups help learners finish.', 'Find the writer''s main point in a short argument.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('c434373f-93a9-5a8a-a80b-a7a3a4bfc9b8', '9418db97-0971-52f4-9984-f14a8d308ca3', 'A', 'Online courses are not flexible.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3170b4db-cf9a-551c-a57a-a27366e61576', '9418db97-0971-52f4-9984-f14a8d308ca3', 'B', 'Structure and social support help learners finish online courses.', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('5bb36908-75e2-56ce-8893-c3dba8fd2967', '9418db97-0971-52f4-9984-f14a8d308ca3', 'C', 'Discussion groups are more useful than courses.', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d1a19b9b-0b16-5ba1-928a-f3fb960fac1f', 'ra-0001', 'a3ae1a47-54fa-53b1-a663-dbb4a3264362', 'beginner', 'Read the text out loud, clearly and at a natural speed.', '{"text": "Many cities now plant trees along busy roads. The trees give shade in summer, reduce noise from traffic and make the streets more pleasant for people who walk to work."}'::jsonb, '{"reference_text": "Many cities now plant trees along busy roads. The trees give shade in summer, reduce noise from traffic and make the streets more pleasant for people who walk to work."}'::jsonb, 'Read in phrases, not word by word. Pause briefly at commas and full stops.', 'Read a short factual text aloud with clear pronunciation and natural phrasing.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0572d759-cf7f-5527-a087-211b3705d256', 'ra-0002', 'a3ae1a47-54fa-53b1-a663-dbb4a3264362', 'intermediate', 'Read the text out loud, clearly and at a natural speed.', '{"text": "Researchers studying sleep have found that teenagers naturally fall asleep later than adults. As a result, some schools have moved their start time to later in the morning, and early reports suggest that attendance has improved."}'::jsonb, '{"reference_text": "Researchers studying sleep have found that teenagers naturally fall asleep later than adults. As a result, some schools have moved their start time to later in the morning, and early reports suggest that attendance has improved."}'::jsonb, 'Stress the content words (researchers, teenagers, later, attendance) and keep a steady pace.', 'Read a longer academic text with correct word stress.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('89b1e8a9-4743-58ee-beca-cf2bb3c7c2d7', 'rs-0001', '7c6899f2-cb0f-51b5-918e-5b3a66defe02', 'beginner', 'Listen to the sentence, then say it back exactly as you heard it.', '{"audio_script": "The library closes at six on Fridays."}'::jsonb, '{"reference_text": "The library closes at six on Fridays."}'::jsonb, 'Listen for meaning, not single words. Remember the sentence as one idea.', 'Hold a short sentence in memory and repeat it accurately.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('6f1134e4-325c-5e6a-87a3-92692ef9f309', 'rs-0002', '7c6899f2-cb0f-51b5-918e-5b3a66defe02', 'intermediate', 'Listen to the sentence, then say it back exactly as you heard it.', '{"audio_script": "Students who submit their assignments late must speak to the course coordinator."}'::jsonb, '{"reference_text": "Students who submit their assignments late must speak to the course coordinator."}'::jsonb, 'Break the sentence into two chunks: who it is about, and what they must do.', 'Repeat a sentence with a relative clause.', array['Content', 'Oral fluency', 'Pronunciation']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('03da1430-4de7-5350-8932-0aa762f68262', 'di-0001', 'f0be0416-0643-5200-8465-6eb775a49e76', 'beginner', 'Look at the picture. Describe the main things it shows and what they mean.', '{"image": {"kind": "bar_chart", "title": "Books borrowed per month at a town library", "data": [{"label": "January", "value": 420}, {"label": "February", "value": 380}, {"label": "March", "value": 510}, {"label": "April", "value": 600}]}}'::jsonb, '{"model_answer": "The bar chart shows how many books a town library lent each month from January to April. Borrowing dipped slightly from 420 in January to 380 in February, then rose steadily to a peak of 600 in April. Overall, the library became busier during spring."}'::jsonb, 'Say what the image is, give the highest and lowest values, describe the trend, then give a conclusion.', 'Describe a simple bar chart using trend language.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['library books per month', 'lowest in February (380)', 'highest in April (600)', 'overall upward trend']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('73724c3a-0c82-5016-88c6-354efafedfef', 'di-0002', 'f0be0416-0643-5200-8465-6eb775a49e76', 'intermediate', 'Look at the picture. Describe the main things it shows and what they mean.', '{"image": {"kind": "pie_chart", "title": "How students travel to a college", "data": [{"label": "Bus", "value": 40}, {"label": "Walk", "value": 25}, {"label": "Bicycle", "value": 20}, {"label": "Car", "value": 15}]}}'::jsonb, '{"model_answer": "The pie chart shows how students get to a college. The bus is the most common choice at forty percent, followed by walking at a quarter. Twenty percent cycle, and only fifteen percent travel by car. In short, most students use low-cost or active travel."}'::jsonb, 'Compare the parts: biggest, smallest and any similar values.', 'Describe proportions in a pie chart.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['student travel to college', 'bus largest (40%)', 'car smallest (15%)', 'walking and cycling together 45%']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('5fee338b-ed83-5fc1-824d-8c51d63dc532', 'rl-0001', '4d460dfa-9371-56a2-b754-40d96c6ad99e', 'intermediate', 'Listen to the talk, then tell it again in your own words.', '{"audio_script": "Today I want to talk about honeybees and why farmers care about them. Bees carry pollen from flower to flower, and this allows many fruit and vegetable plants to produce food. In some regions, bee numbers have fallen because of disease, loss of wild flowers and certain pesticides. Some farmers now plant strips of wild flowers beside their fields to give bees food and shelter."}'::jsonb, '{"model_answer": "The lecture explained that bees are important to farmers because they pollinate many food crops. Bee numbers have dropped in some places because of disease, fewer wild flowers and pesticides. To help, some farmers grow wild flower strips next to their fields."}'::jsonb, 'Note the topic, two or three main points and the conclusion. Use your own words.', 'Retell the main ideas of a short lecture.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['bees pollinate crops', 'bee numbers falling', 'causes: disease, fewer flowers, pesticides', 'farmers plant wild flower strips']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7ff218f2-772c-5ec2-9a21-838f150487d9', 'rl-0002', '4d460dfa-9371-56a2-b754-40d96c6ad99e', 'advanced', 'Listen to the talk, then tell it again in your own words.', '{"audio_script": "The idea of a four-day working week has moved from theory to real trials. In several trials, staff kept the same pay but worked one day less. Many companies reported similar output, while employees described less stress and better sleep. Critics argue that the results may not apply to jobs such as hospital care, where someone must always be present."}'::jsonb, '{"model_answer": "The speaker discussed trials of a four-day working week with no cut in pay. Many firms kept the same output and workers reported lower stress and better sleep. However, critics say the model may not suit jobs like hospital work that need constant cover."}'::jsonb, 'Include the contrast at the end: the benefits and the criticism.', 'Retell a lecture that includes a counter-argument.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['four-day week trials', 'same pay, one day less', 'similar output, less stress', 'may not suit jobs needing constant cover']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d2672795-e931-53dc-a18d-5ad0db18ad0a', 'asq-0001', 'f26d9c2f-752a-5177-be36-02d0006010a2', 'beginner', 'Listen to the question and answer it in one or a few words.', '{"audio_script": "What do we call the meal people usually eat in the morning?"}'::jsonb, '{"accepted": ["breakfast"]}'::jsonb, 'The morning meal is breakfast.', 'Answer an everyday knowledge question with one word.', array['Vocabulary']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ea5c076d-3472-53d1-9f6a-e602b2638bec', 'asq-0002', 'f26d9c2f-752a-5177-be36-02d0006010a2', 'beginner', 'Listen to the question and answer it in one or a few words.', '{"audio_script": "How many sides does a triangle have?"}'::jsonb, '{"accepted": ["three", "3"]}'::jsonb, 'A triangle has three sides.', 'Answer a basic maths question quickly.', array['Vocabulary']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('784c7b11-4dbc-5f37-912d-1fb489c69314', 'sgd-0001', '71a77aef-e49f-5acc-a085-deaa6bf6488d', 'intermediate', 'Listen to the discussion, then say what the main points were in your own words.', '{"speakers": ["Amira", "Ben", "Chen"], "audio_script": [{"speaker": "Amira", "text": "I think the university should keep the library open all night during exams."}, {"speaker": "Ben", "text": "That sounds good, but who pays for the extra staff and security?"}, {"speaker": "Chen", "text": "Maybe we could open just one floor overnight, with self-service machines, to keep costs down."}]}'::jsonb, '{"model_answer": "The students discussed opening the library all night during exams. Amira supported the idea, Ben worried about the cost of staff and security, and Chen suggested a compromise of opening one self-service floor overnight."}'::jsonb, 'Name each speaker''s position and the final suggestion.', 'Summarize different opinions in a short discussion.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['proposal: open library overnight in exams', 'concern: cost of staff and security', 'compromise: one self-service floor']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c9b5e3c3-f80a-5721-ba09-c671806507e6', 'sgd-0002', '71a77aef-e49f-5acc-a085-deaa6bf6488d', 'advanced', 'Listen to the discussion, then say what the main points were in your own words.', '{"speakers": ["Dana", "Eli", "Farah"], "audio_script": [{"speaker": "Dana", "text": "Our group project should use online meetings, because we all live far apart."}, {"speaker": "Eli", "text": "Online is convenient, but last time people turned their cameras off and nobody spoke."}, {"speaker": "Farah", "text": "Then let''s meet online each week but set a short agenda and give everyone a task to report on."}]}'::jsonb, '{"model_answer": "The group talked about how to meet for their project. Dana preferred online meetings because members live far apart. Eli agreed they are convenient but said people did not take part last time. Farah proposed weekly online meetings with an agenda and a task for each person."}'::jsonb, 'Show how the ideas build on each other to reach a solution.', 'Summarize a discussion that reaches a solution.', array['Content', 'Oral fluency', 'Pronunciation']::text[], array['online meetings because of distance', 'problem: low participation', 'solution: agenda and tasks for everyone']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('5a29b083-8a4c-5dd5-8adc-377fa199303f', 'rts-0001', 'd74a6ad6-8f3a-5163-9210-faac5c28e9e4', 'beginner', 'Read and listen to the situation, then say what you would say in it.', '{"situation": "You borrowed a classmate''s notes for a week, but you spilled coffee on one page. You are going to return the notes now. What do you say to your classmate?"}'::jsonb, '{"model_answer": "Hi Jamie, thank you so much for lending me your notes. I''m really sorry, but I spilled some coffee on page four. I''ve copied that page out neatly for you, and I''m happy to buy you a coffee to say sorry."}'::jsonb, 'Thank the person, explain the problem honestly, apologise and offer a solution.', 'Apologise politely and offer a solution.', array['Appropriacy', 'Oral fluency', 'Pronunciation']::text[], array['thank', 'explain the problem', 'apologise', 'offer a fix']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a240ced8-2d59-59e2-abed-fbddea0465f7', 'rts-0002', 'd74a6ad6-8f3a-5163-9210-faac5c28e9e4', 'intermediate', 'Read and listen to the situation, then say what you would say in it.', '{"situation": "Your manager has asked you to work this Saturday, but you have already booked a train ticket to visit your family. What do you say to your manager?"}'::jsonb, '{"model_answer": "Thanks for thinking of me for Saturday. Unfortunately, I''ve already booked a train to visit my family that day, so I can''t come in. Could I help by staying late on Thursday or Friday, or by finishing part of the work from home before I leave?"}'::jsonb, 'Decline politely, give a reason and offer an alternative.', 'Decline a request politely in a work setting.', array['Appropriacy', 'Oral fluency', 'Pronunciation']::text[], array['polite refusal', 'clear reason', 'alternative offer']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1366d92b-83a3-5323-9e16-36f5c61d251d', 'swt-0001', '592287fc-2723-5ab2-812f-f18d75a3190f', 'intermediate', 'Read the passage, then sum up its main idea in one sentence.', '{"passage": "Community gardens are spaces where neighbours grow vegetables and flowers together on shared land. Supporters say they improve access to fresh food, especially in areas with few shops. They also bring people of different ages and backgrounds together, which can reduce loneliness. However, gardens often depend on volunteers and temporary agreements with landowners, so many struggle to survive for more than a few years."}'::jsonb, '{"model_answer": "Community gardens improve access to fresh food and bring neighbours together, but their reliance on volunteers and temporary land agreements often makes them hard to sustain."}'::jsonb, 'Combine the main benefit and the main problem in one sentence with a linking word such as "but".', 'Write a one-sentence summary that links ideas.', array['Content', 'Form', 'Grammar', 'Vocabulary']::text[], array['fresh food access', 'bring people together', 'depend on volunteers and temporary land']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('650de8f8-7a34-50dd-af02-4003654b217f', 'swt-0002', '592287fc-2723-5ab2-812f-f18d75a3190f', 'advanced', 'Read the passage, then sum up its main idea in one sentence.', '{"passage": "Electric scooters for hire have spread quickly through many cities. They offer a cheap and fast way to make short trips without a car. Yet city councils have raised concerns about riders using pavements, scooters left blocking paths, and injuries among inexperienced users. In response, some cities now require parking zones, speed limits in busy areas and helmets for younger riders."}'::jsonb, '{"model_answer": "Although hire e-scooters provide cheap, fast short trips, safety and obstruction concerns have led some cities to introduce parking zones, speed limits and helmet rules."}'::jsonb, 'Use "although" to show the contrast, then give the response.', 'Summarize a problem-solution text in one sentence.', array['Content', 'Form', 'Grammar', 'Vocabulary']::text[], array['cheap fast short trips', 'safety and blocking concerns', 'rules: parking zones, speed limits, helmets']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('2f54806e-1a14-5c38-b358-c020d863578a', 'we-0001', 'cefac6c4-c50a-586c-b734-2ea833cbec6b', 'intermediate', 'Write an essay on the topic. Give your opinion and support it with reasons and examples.', '{"prompt": "Some people believe that university education should be free for all students. Others think students should pay part of the cost. Discuss both views and give your own opinion."}'::jsonb, '{"outline": ["Introduction: restate topic and give opinion", "Body 1: arguments for free education", "Body 2: arguments for students paying", "Conclusion: summary and opinion"]}'::jsonb, 'Plan four paragraphs. Support each idea with a reason and an example.', 'Write a balanced discussion essay.', array['Content', 'Form', 'Development, structure and coherence', 'Grammar', 'General linguistic range', 'Vocabulary range', 'Spelling']::text[], array['benefits of free education', 'reasons for student contribution', 'clear personal opinion']::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('64a4f1d7-c03e-5d9c-b4bf-9ad233e0b49b', 'we-0002', 'cefac6c4-c50a-586c-b734-2ea833cbec6b', 'advanced', 'Write an essay on the topic. Give your opinion and support it with reasons and examples.', '{"prompt": "Working from home has become common in many jobs. Do the advantages of working from home outweigh the disadvantages?"}'::jsonb, '{"outline": ["Introduction: context and position", "Body 1: advantages (time, flexibility)", "Body 2: disadvantages (isolation, communication)", "Conclusion: weighed judgement"]}'::jsonb, 'Make your position clear in the introduction and repeat it in the conclusion.', 'Write an advantages-disadvantages essay with a clear position.', array['Content', 'Form', 'Development, structure and coherence', 'Grammar', 'General linguistic range', 'Vocabulary range', 'Spelling']::text[], array['advantages of remote work', 'disadvantages of remote work', 'clear judgement']::text[], 'published');
insert into public.placement_tests (id, slug, title, version, estimated_minutes, items) values ('05283f5f-0130-56e3-83f6-d86c83815425', 'placement-v1', 'Placement test', 1, 15, '[{"id": "d1-r", "level": 1, "skill": "reading", "type": "single_choice", "passage": "Hi, I am Tom. I am ten years old. I have a dog.", "prompt": "How old is Tom?", "options": ["Eight", "Ten", "Twelve"], "answer": "Ten"}, {"id": "d1-w", "level": 1, "skill": "writing", "type": "single_choice", "prompt": "Choose the correct sentence.", "options": ["She are my sister.", "She is my sister.", "She am my sister."], "answer": "She is my sister."}, {"id": "d1-l", "level": 1, "skill": "listening", "type": "single_choice", "audio_script": "Good morning. My name is Sara and I live in a small house.", "prompt": "Where does Sara live?", "options": ["In a small house", "In a big flat", "In a hotel"], "answer": "In a small house"}, {"id": "d2-r", "level": 2, "skill": "reading", "type": "single_choice", "passage": "The shop opens at nine and closes at six. On Sundays it is closed.", "prompt": "When can you NOT visit the shop?", "options": ["Monday morning", "Saturday afternoon", "Sunday"], "answer": "Sunday"}, {"id": "d2-w", "level": 2, "skill": "writing", "type": "single_choice", "prompt": "Yesterday we ___ to the park.", "options": ["go", "went", "going"], "answer": "went"}, {"id": "d2-l", "level": 2, "skill": "listening", "type": "single_choice", "audio_script": "The train to the city leaves from platform four at half past three.", "prompt": "When does the train leave?", "options": ["3:30", "4:00", "4:30"], "answer": "3:30"}, {"id": "d3-r", "level": 3, "skill": "reading", "type": "single_choice", "passage": "Although the new library is further from the town centre, most students prefer it because it stays open until midnight and has quiet study rooms.", "prompt": "Why do most students prefer the new library?", "options": ["It is closer to the centre", "It has longer opening hours and quiet rooms", "It is cheaper to use"], "answer": "It has longer opening hours and quiet rooms"}, {"id": "d3-w", "level": 3, "skill": "writing", "type": "single_choice", "prompt": "If it ___ tomorrow, we will cancel the trip.", "options": ["rains", "will rain", "rained"], "answer": "rains"}, {"id": "d3-l", "level": 3, "skill": "listening", "type": "single_choice", "audio_script": "I was going to study medicine, but after volunteering at a school I realised that teaching was what I really wanted to do.", "prompt": "What did the speaker decide to do?", "options": ["Study medicine", "Become a teacher", "Work in a hospital"], "answer": "Become a teacher"}, {"id": "d4-r", "level": 4, "skill": "reading", "type": "single_choice", "passage": "Remote work has reduced commuting time for many employees. However, some managers report that spontaneous collaboration has declined, which may slow down the development of new ideas.", "prompt": "What concern do some managers have?", "options": ["Employees commute more", "Fewer unplanned conversations may slow innovation", "Remote work costs more money"], "answer": "Fewer unplanned conversations may slow innovation"}, {"id": "d4-w", "level": 4, "skill": "writing", "type": "single_choice", "prompt": "Choose the best word: The results were ___ with earlier studies.", "options": ["consistent", "constant", "considerate"], "answer": "consistent"}, {"id": "d4-l", "level": 4, "skill": "listening", "type": "single_choice", "audio_script": "While the treatment was effective for most patients, researchers noted that its benefits were smaller among older adults, so further trials are needed for that group.", "prompt": "What do the researchers say is needed?", "options": ["More trials with older adults", "A cheaper treatment", "No further research"], "answer": "More trials with older adults"}, {"id": "d5-r", "level": 5, "skill": "reading", "type": "single_choice", "passage": "The author contends that economic growth alone is an inadequate measure of national progress, since it disregards inequality, environmental degradation and the unpaid work that sustains households.", "prompt": "What is the author''s main argument?", "options": ["Growth should be the only measure of progress", "Growth ignores important aspects of progress", "Unpaid work should be taxed"], "answer": "Growth ignores important aspects of progress"}, {"id": "d5-w", "level": 5, "skill": "writing", "type": "single_choice", "prompt": "Choose the correct sentence.", "options": ["Hardly had we arrived when the meeting started.", "Hardly we had arrived when the meeting started.", "Hardly had we arrived than the meeting started."], "answer": "Hardly had we arrived when the meeting started."}, {"id": "d5-l", "level": 5, "skill": "listening", "type": "single_choice", "audio_script": "Critics of the policy argue that, far from encouraging innovation, the subsidies have mainly benefited established firms that would have invested anyway.", "prompt": "What do critics say about the subsidies?", "options": ["They strongly encouraged new firms", "They mostly helped companies that did not need them", "They were too small to matter"], "answer": "They mostly helped companies that did not need them"}, {"id": "d6-r", "level": 6, "skill": "reading", "type": "single_choice", "passage": "Notwithstanding its methodological elegance, the study''s reliance on self-reported data renders its conclusions about actual behaviour somewhat tentative.", "prompt": "What weakness of the study does the writer point out?", "options": ["Its methods are too complicated", "Participants'' own reports may not match what they really do", "It studied too many people"], "answer": "Participants'' own reports may not match what they really do"}, {"id": "d6-w", "level": 6, "skill": "writing", "type": "single_choice", "prompt": "Choose the most precise word: The committee''s decision was ___, so it could not be challenged later.", "options": ["irrevocable", "irrelevant", "irregular"], "answer": "irrevocable"}, {"id": "d6-l", "level": 6, "skill": "listening", "type": "single_choice", "audio_script": "The archive''s value lies less in any single document than in the way the collection, taken as a whole, reveals shifting attitudes over two centuries.", "prompt": "According to the speaker, why is the archive valuable?", "options": ["One famous document is in it", "The whole collection shows how attitudes changed", "It is two centuries old"], "answer": "The whole collection shows how attitudes changed"}]'::jsonb);
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change) values ('00000000-0000-0000-0000-000000000000', '09e72f04-37e7-59e4-b691-004672efbcd9', 'authenticated', 'authenticated', 'demo.student@example.test', extensions.crypt('DemoStudent-123!', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, '{"display_name": "Demo Student", "age_confirmed": "true", "terms_accepted": "true"}'::jsonb, now(), now(), '', '', '', '');
insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at) values ('48ec3cff-a6ce-5b7b-b644-f4fe865f7601', '09e72f04-37e7-59e4-b691-004672efbcd9', '09e72f04-37e7-59e4-b691-004672efbcd9', '{"sub": "09e72f04-37e7-59e4-b691-004672efbcd9", "email": "demo.student@example.test", "email_verified": true}'::jsonb, 'email', now(), now(), now());
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change) values ('00000000-0000-0000-0000-000000000000', '492a9b78-e2f5-5f88-88f0-c585b74a7f6b', 'authenticated', 'authenticated', 'demo.admin@example.test', extensions.crypt('DemoAdmin-123!', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, '{"display_name": "Demo Admin", "age_confirmed": "true", "terms_accepted": "true"}'::jsonb, now(), now(), '', '', '', '');
insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at) values ('ef5e5e6f-b596-514a-96c5-6a0b89f0476d', '492a9b78-e2f5-5f88-88f0-c585b74a7f6b', '492a9b78-e2f5-5f88-88f0-c585b74a7f6b', '{"sub": "492a9b78-e2f5-5f88-88f0-c585b74a7f6b", "email": "demo.admin@example.test", "email_verified": true}'::jsonb, 'email', now(), now(), now());
insert into public.user_roles (user_id, role) values ('492a9b78-e2f5-5f88-88f0-c585b74a7f6b', 'admin');
